/* Ce que les annales disent des 4 premières semaines (phrases copiées des corrections). */
window.SDE = [{"week":1,"stages":[{"day":"J0-J3","label":"Fécondation, zygote et séjour dans l'ampoule tubaire","events":[{"t":"Elle migre ensuite entre J0 et J3.","s":"BANQUE Première semaine du développement Concours blanc PASS - 2020-2021 Q2"},{"t":"Dans le cours, il est plutôt question de J0 à J4.","s":"ANNALE Rattrapage 2022-2023 Q2"}]},{"day":"J2","label":"Stade 4 cellules (segmentation asynchrone)","events":[{"t":"début J2 on a environ 4 cellules donc on ne peut pas réellement savoir selon leur positionnement si elles participeront au trophoblaste ou au bouton embryonnaire.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q49"},{"t":"Le stade « 3 blastomères » justifie le terme d’« asynchrone » pour caractériser la segmentation de l’œuf humain.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"}]},{"day":"J3","label":"Stade 8 cellules, activation du génome embryonnaire","events":[{"t":"Le stade 8 cellules a lieu à J3 (23=8), ainsi c’est un stade qui précède la compaction de la morula, évènement marquant la perte de la totipotence des cellules.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"L’activation du génome embryonnaire a lieu à J3, donc avant le stade morula (J4).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"Les jonctions d’adhésion apparaissent au stade 6-8 blastomères, à J3.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q46"}]},{"day":"J4","label":"Morula compactée, jonctions serrées, perte de la totipotence","events":[{"t":"La compaction est liée à l’apparition de jonctions serrées à J4.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"La perte de la totipotence se fait lors de la compaction de la morula vers fin J4.","s":"BANQUE Première semaine du développement Concours blanc 1 2019/2020 Q18"},{"t":"L’œuf arrive dans l’utérus à début J4 soit au stade la morula non compactée","s":"BANQUE Première semaine du développement Concours blanc 1 2019/2020 Q24"},{"t":"Au début de J4, l’embryon possède 16 cellules. Il prend alors l’aspect d’une petite mûre : on l’appelle donc morula.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q74"}]},{"day":"J5","label":"Blastocyste : cavitation, blastocèle, MCI / trophoblaste","events":[{"t":"Le blastocyste se forme d’ailleurs à J5-J6.","s":"ANNALE Rattrapage 2022-2023 Q2"},{"t":"La formation du blastocèle a lieu à J5.","s":"BANQUE Première semaine du développement Concours blanc 1 2019/2020 Q23"},{"t":"Lors de la cavitation à J5, le gradient osmotique permet de faire passer de l’eau à l’intérieur de l’embryon.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q42"},{"t":"Jusqu’à J5 la zone pellucide (ZP) est inextensible mais elle est toujours présente.","s":"BANQUE Première semaine du développement Concours blanc 1 - 2020-2021 Q12"}]},{"day":"J6","label":"Expansion du blastocyste, amincissement et éclosion de la zone pellucide","events":[{"t":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"À J6, le diamètre du blastocyste est quasiment multiplié par deux.","s":"BANQUE Première semaine du développement Concours blanc 1 2019/2020 Q19"},{"t":"La zone pellucide est inextensible jusqu’à J6, c’est pourquoi le diamètre de l’oeuf est constant jusqu’à cette date.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q63"}]},{"day":"J5-J8","label":"Fenêtre d'implantation","events":[{"t":"La fenêtre temporelle d’implantation a lieu entre J5 et J8 du développement embryonnaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"L’implantation a lieu entre J4 et J7.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"}]}],"structs":[{"name":"Blastocyste (MCI, trophoblaste, blastocèle)","facts":[{"t":"Le blastocyste s’expand pour mesurer jusqu’à 200-220 µm de diamètre.","s":"ANNALE Épreuve terminale 2024-2025 Q5"},{"t":"Le blastocyste se forme d’ailleurs à J5-J6.","s":"ANNALE Rattrapage 2022-2023 Q2"},{"t":"Un zygote possède une chance sur deux d’atteindre le stade de blastocyste.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"t":"Le blastocyste s’oriente puis éclos, s’appose et adhère à l’endomètre","s":"ANNALE Épreuve terminale 2024-2025 Q6"}],"pieges":[{"f":"A partir du stade de blastocyste, les transcrits maternels et embryonnaires sont utilisés, c’est la transition materno-fœtale.","c":"Les transcrits maternels sont utilisés jusqu’à environ J3 et les transcrits embryonnaires sont utilisés environ à partir de J3. Or, le blastocyste se forme à J5-J6.","s":"ANNALE Épreuve terminale 2022-2023 Q19"},{"f":"La formation du blastocèle est un phénomène passif indépendant de la pompe NA+/K+ ATPase.","c":"Au contraire la formation de la blastocèle est dépendante de la pompe Na+/K+ pour permettre les entrées d’eau. Il s’agit donc d’un phénomène actif.","s":"ANNALE Contrôle continu 2024-2025 Q11"}]},{"name":"Morula / compaction","facts":[{"t":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"La compaction est liée à l’apparition de jonctions serrées à J4.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"Le stade 8 cellules a lieu à J3 (23=8), ainsi c’est un stade qui précède la compaction de la morula, évènement marquant la perte de la totipotence des cellules.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"L’activation du génome embryonnaire a lieu à J3, donc avant le stade morula (J4).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"}],"pieges":[{"f":"Le diamètre des blastomères reste constant jusqu’au stade morula.","c":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible. Le diamètre est quasiment multiplié par 2 à ce moment-là.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"f":"La compaction est en relation avec l’apparition de jonctions d’adhésion à J4 .","c":"La compaction est liée à l’apparition de jonctions serrées à J4.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"}]},{"name":"Segmentation (blastomères, stades 2-4-8 cellules)","facts":[{"t":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"Le stade 8 cellules a lieu à J3 (23=8), ainsi c’est un stade qui précède la compaction de la morula, évènement marquant la perte de la totipotence des cellules.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"Les premières étapes de segmentation de l'embryon sont asymétriques et asynchrones.","s":"ANNALE Contrôle continu 2024-2025 Q11"},{"t":"Lors des premières étapes de segmentation de l’embryon, les cellules sont totipotentes.","s":"ANNALE Contrôle continu 2024-2025 Q11"}],"pieges":[{"f":"Le diamètre des blastomères reste constant jusqu’au stade morula.","c":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible. Le diamètre est quasiment multiplié par 2 à ce moment-là.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"f":"Les premières étapes de segmentation de l'embryon sont symétriques et synchrones","c":"La segmentation de l’œuf est AAAsymétrique, AAAsynchrone et totAAAle.","s":"ANNALE CC Embryologie 2023-2024 Q11"}]},{"name":"Zygote / fécondation","facts":[{"t":"elle est bien pré-implantatoire mais la fécondation suit l’ovulation, de J1-J7","s":"ANNALE Épreuve terminale 2024-2025 Q5"},{"t":"Un zygote possède une chance sur deux d’atteindre le stade de blastocyste.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"t":"Le stade « 3 blastomères » est lié au fait qu’une des 2 cellules du zygote juste va se diviser avant l’autre, ce qui justifie bien le terme d’asynchrone pour qualifier la division humaine.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"Pour savoir à quel jour du cycle maternel ils correspondent, il faut ajouter 15 jours (car la fécondation se produit aux alentours de J15 du cycle maternel).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"}],"pieges":[{"f":"Les premières étapes de segmentation de l'embryon s'effectuent du stade zygote au stade blastocyste","c":"Les premières étapes vont jusqu’au stade morula.","s":"ANNALE CC Embryologie 2023-2024 Q11"},{"f":"La première semaine de développement embryonnaire est une période pré-implantatoire qui débute 7 jours après l’ovulation.","c":"elle est bien pré-implantatoire mais la fécondation suit l’ovulation, de J1-J7","s":"ANNALE Épreuve terminale 2024-2025 Q5"}]},{"name":"Migration tubaire / GEU","facts":[{"t":"Par ailleurs, les GEU sont à 98% des GEU tubaires.","s":"ANNALE Rattrapage 2022-2023 Q2"},{"t":"Un défaut de migration de l'embryon lors de la première semaine de développement embryonnaire peut être à l'origine d'une grossesse extra utérine","s":"ANNALE CC Embryologie 2023-2024 Q11"},{"t":"L’embryon migre lentement de la trompe vers l’utérus grâce notamment aux sécrétions tubaires.","s":"ANNALE Épreuve terminale 2024-2025 Q5"},{"t":"L’embryon se développe de manière continue de l’ampoule de la trompe utérine, où il se développe pendant 3 jours, puis migre jusqu’à la cavité.","s":"ANNALE Épreuve terminale 2022-2023 Q20"}],"pieges":[{"f":"L’embryon migre rapidement de l’ampoule tubaire à la cavité utérine grâce à d’importantes contractions utérines.","c":"La migration est lente.","s":"ANNALE Épreuve terminale 2022-2023 Q20"},{"f":"L’embryon se déplace activement de l’ampoule de la trompe jusqu’à la cavité utérine en 5 à 6 jours.","c":"C’est une migration passive permise par les sécrétions tubaires et les contractions utérines hormono-dépendantes.","s":"ANNALE Rattrapage 2022-2023 Q2"}]},{"name":"Éclosion / zone pellucide","facts":[{"t":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"A J6 a lieu l’amincissement de la zone pellucide.","s":"BANQUE Première semaine du développement Concours blanc 1 2019/2020 Q32"},{"t":"Si de manière artificielle on enlève la zone pellucide à J3, les cellules vont rester associées.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q49"},{"t":"La zone pellucide est inextensible jusqu’à J6, c’est pourquoi le diamètre de l’oeuf est constant jusqu’à cette date.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q63"}],"pieges":[{"f":"Le diamètre des blastomères reste constant jusqu’au stade morula.","c":"Le diamètre des blastomères reste constant jusqu’au moment de l’expansion à J6 (donc après le stade morula), stade durant lequel on observe un amincissement de la Zone Pellucide qui était jusque là inextensible. Le diamètre est quasiment multiplié par 2 à ce moment-là.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"f":"Le phénomène de cavitation et la disparition de la zone pellucide.","c":"Le phénomène de cavitation a lieu à J5 alors que l’éclosion et donc la disparition de la ZP a lieu à J6.","s":"BANQUE Première semaine du développement Concours blanc 1 - 2020-2021 Q8"}]},{"name":"Activation du génome embryonnaire","facts":[{"t":"Les transcrits maternels sont utilisés jusqu’à J3 environ.","s":"ANNALE Épreuve terminale 2022-2023 Q19"},{"t":"L’activation du génome embryonnaire a lieu à J3, donc avant le stade morula (J4).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"Au cours de stades de segmentation embryonnaire, les transcrits maternels sont utilisés.","s":"ANNALE Épreuve terminale 2022-2023 Q19"},{"t":"Au troisième jour de développement embryonnaire, le génome embryonnaire s’active.","s":"ANNALE Rattrapage 2022-2023 Q2"}],"pieges":[{"f":"La reprogammation du génome embryonnaire débute lorsque le spermatozoïde féconde l’ovocyte.","c":"Elle a lieu à J3","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"f":"A partir du stade de blastocyste, les transcrits maternels et embryonnaires sont utilisés, c’est la transition materno-fœtale.","c":"Les transcrits maternels sont utilisés jusqu’à environ J3 et les transcrits embryonnaires sont utilisés environ à partir de J3. Or, le blastocyste se forme à J5-J6.","s":"ANNALE Épreuve terminale 2022-2023 Q19"}]},{"name":"Jonctions (serrées / communicantes)","facts":[{"t":"La compaction est liée à l’apparition de jonctions serrées à J4.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q19"},{"t":"Toutes les cellules de la morula possèdent des jonctions communicantes.","s":"ANNALE Épreuve terminale 2024-2025 Q5"},{"t":"Les jonctions serrées sont présentes uniquement entre les cellules externes de la morula.","s":"ANNALE Contrôle continu 2024-2025 Q11"},{"t":"Les jonctions serrées ont lieu entre les cellules externes et les jonctions communicantes ont lieu entre les cellules internes et externes.","s":"ANNALE Épreuve terminale 2022-2023 Q19"}],"pieges":[{"f":"À partir du stade morula, les cellules acquièrent une polarité et sont toutes liées entre elles par des jonctions serrées.","c":"Les jonctions serrées sont présentes uniquement entre les cellules externes de la morula.","s":"ANNALE Contrôle continu 2024-2025 Q11"},{"f":"Lors de la période de compaction, les cellules embryonnaires sont polarisées et ils existent des jonctions serrées entre les cellules externes et internes.","c":"Les jonctions serrées ont lieu entre les cellules externes et les jonctions communicantes ont lieu entre les cellules internes et externes.","s":"ANNALE Épreuve terminale 2022-2023 Q19"}]},{"name":"Cellules souches / pluripotence","facts":[{"t":"La pluripotence est l’aptitude d’une cellule à générer plusieurs types cellulaires.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"t":"Les cellules souches dérivent des cellules de la masse cellulaire interne d’un blastocyste","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"La masse cellulaire interne est ce qui va donner l’embryon à proprement dit, les cellules souches dérivent donc forcément de la masse cellulaire interne.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q20"},{"t":"Au stade de la morula compactée, fin J4, les cellules sont pluripotentes.","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q48"}],"pieges":[{"f":"À partir de ce stade, on considère que l’embryon perd sa totipotence et devient pluripotent.","c":"il devient pluripotent au stade morula (16 cellules).","s":"BANQUE Première semaine du développement Concours blanc 2016/2017 Q65"},{"f":"Les hématies dérivées de la population initiale de cellules souches chez l’embryon sont anucléées tout comme celle de la circulation maternelle.","c":"Au contraire elles sont nucléées ce qui permet de faire un diagnostic génétique sans avoir à effectuer une amniocentèse en le recherchant dans la circulation maternelle.","s":"BANQUE Mise en place de l’appareil circulatoire Epreuve majeure 2 – 2018/2019 Q22"}]}]},{"week":2,"stages":[{"day":"J7","label":"Prégastrulation : disque didermique (épiblaste + hypoblaste)","events":[{"t":"Le disque didermique (épiblaste + hypoblaste) apparaît à J7, durant la prégastrulation, marquant la seule transformation de la MCI cette semaine.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"A J7 se met en place le disque didermique : les cellules en regard du blastocèle forment l’hypoblaste et les cellules au-dessus forment l’ectoblaste.","s":"BANQUE Deuxième semaine du développement New 2023-2024 Q1"},{"t":"Entre J7 et J8, les cellules du trophoblaste s’infiltrent et remplacent les cellules de l’épithélium utérin, elles constituent une couche de cellules cubiques monostratifiées (cellules bleues sur le schéma), c’est le cytotrophoblaste.","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2017/2018 Q39"}]},{"day":"J8","label":"Syncytiotrophoblaste / cytotrophoblaste, cavité amniotique, mésenchyme extra-embryonnaire","events":[{"t":"Dès J8, le trophoblaste se différencie en syncytiotrophoblaste (invasif) et cytotrophoblaste (couche cellulaire unique).","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"La cavité amniotique se forme à J8, tout comme le mésenchyme extra-embryonnaire (autrement appelé magma réticulé).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"l’épiblaste se creuse d’une cavité à J8, on obtient alors l’amnios, l’épiblaste, la cavité amniotique","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q52"}]},{"day":"J9","label":"Lécithocèle primaire (membrane de Heuser), œuf à moitié implanté","events":[{"t":"Le lécithocèle primaire se forme lui à J9, le mésenchyme est encore présent à ce moment-là.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2017/2018 Q49"},{"t":"L’œuf est à moitié implanté à J9 et totalement implanté à J10.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"La membrane de Heuser est bien une membrane cellulaire (attention aux pièges) qui ferme le lécithocèle primaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"}]},{"day":"J10","label":"Œuf entièrement implanté, lacunes du syncytiotrophoblaste remplies de sang maternel, hCG","events":[{"t":"Vers J10, l’œuf est entièrement implanté dans l’endomètre et du sang maternel est présent dans le syncytiotrophoblaste.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Les lacunes du syncytiotrophoblaste (qui ne sont PAS bordées par un épithélium) commencent en effet à se remplir de sang vers J10.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"L’HCG peut être détectée dans le sang à partir de J10 et dans les urines dès J11.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"}]},{"day":"J11-J13","label":"Résorption du mésenchyme extra-embryonnaire, cœlome extra-embryonnaire, lames choriale / amniotique / vitelline","events":[{"t":"Le mésenchyme extra-embryonnaire se résorbe partiellement à partir de J11 en laissant trois lames mésenchymateuses : la lame choriale, la lame vitelline et la lame amniotique.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Le mésenchyme extra-embryonnaire régresse partiellement par apoptose, ce qui forme le cœlome extra-embryonnaire fin J13.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"À partir de J11–J13, le mésenchyme extra-embryonnaire (magma réticulé) se résorbe, formant le cœlome externe et trois lames mésenchymateuses : choriale, vitelline, amniotique.","s":"ANNALE Rattrapage 2023-2024 Q9"}]},{"day":"J13","label":"Fin de la nidation, lécithocèle secondaire, cellules déciduales","events":[{"t":"fin de la nidation à J13, l’embryon est complètement implanté dans l’endomètre","s":"ANNALE Épreuve terminale 2024-2025 Q6"},{"t":"Il s’agit des cellules limitant l’invasion du syncytiotrophoblaste et donc protégeant les tissus maternels.","s":"ANNALE Contrôle continu 2024-2025 Q12"},{"t":"Le lécithocèle secondaire se forme entre J11 et J13.","s":"BANQUE Deuxième semaine du développement Concours blanc 2 – 2020/2021 Q6"}]}],"structs":[{"name":"Lames choriale / amniotique / vitelline, pédicule embryonnaire","facts":[{"t":"A partir de J18 du développement embryonnaire, le mésenchyme extra-embryonnaire provenant de la lame choriale va se différencier en angioblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"Le mésenchyme extra-embryonnaire se résorbe partiellement à partir de J11 en laissant trois lames mésenchymateuses : la lame choriale, la lame vitelline et la lame amniotique.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Les villosités tertiaires sont localisées sur la totalité de la surface de la lame choriale","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"Les ilots sanguino-formateurs de « Wolff & Pander » apparaissent initialement au sein de la lame vitelline","s":"ANNALE Rattrapage 2023-2024 Q3"}],"pieges":[{"f":"Les angioblastes proviennent de la lame amniotique.","c":"justement la lame amniotique ne comprend aucun angioblaste","s":"ANNALE Épreuve terminale 2024-2025 Q7"},{"f":"Les villosités secondaires sont localisées sur la lame amniotique","c":"Sur la lame choriale","s":"ANNALE Épreuve terminale 2022-2023 Q21"}]},{"name":"Cavité amniotique / amnios","facts":[{"t":"La cavité amniotique se forme en même temps qu’apparaît du mésenchyme extra-embryonnaire (J8)","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"La cavité amniotique se forme à J8, tout comme le mésenchyme extra-embryonnaire (autrement appelé magma réticulé).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"Le canal chordal établit la communication la cavité amniotique et le lécithocèle secondaire à J16 avant d’évoluer en canal neurentérique en J17 qui va également assurer cette communication.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Le canal chordal puis le canal neurentérique établissent une communication entre la cavité amniotique et le lécithocèle secondaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}],"pieges":[{"f":"Le 6 représente la cavité amniotique.","c":"Il s’agit du lécithocèle secondaire. 5 et 6 ont été inversés entre les items B et C.","s":"ANNALE Contrôle continu 2024-2025 Q12"},{"f":"Le disque didermique est composé du plafond de la cavité amniotique et du plancher de la vésicule vitelline","c":"c’est l’inverse !","s":"ANNALE Épreuve terminale 2024-2025 Q6"}]},{"name":"Implantation / nidation / endomètre","facts":[{"t":"Vers J10, l’œuf est entièrement implanté dans l’endomètre et du sang maternel est présent dans le syncytiotrophoblaste.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"La fenêtre temporelle d’implantation a lieu entre J5 et J8 du développement embryonnaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"L’implantation a lieu entre J4 et J7.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"t":"fin de la nidation à J13, l’embryon est complètement implanté dans l’endomètre","s":"ANNALE Épreuve terminale 2024-2025 Q6"}],"pieges":[{"f":"Elle débute lorsque l’embryon est niché dans l’endomètre.","c":"L’implantation a lieu entre J4 et J7.","s":"ANNALE CC1 Embryologie 2022-2023 Q4"},{"f":"La fenêtre d’implantation s’ouvre au cours de la phase de segmentation","c":"La segmentation de l’œuf se déroule durant la première semaine. La fenêtre temporelle d’implantation a lieu entre J5 et J8 du développement embryonnaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"}]},{"name":"Épiblaste / hypoblaste (disque didermique)","facts":[{"t":"L’hypoblaste prend le nom d’endoblaste à la 3ème semaine après la mise en place du 3ème feuillet à J18.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Le disque didermique (épiblaste + hypoblaste) apparaît à J7, durant la prégastrulation, marquant la seule transformation de la MCI cette semaine.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Le disque embryonnaire didermique est formé par l'épiblaste et l'hypoblaste","s":"ANNALE CC Embryologie 2023-2024 Q12"},{"t":"L’endoblaste dérive de l’hypoblaste et est constitué majoritairement de cellules mésoblastiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}],"pieges":[{"f":"Le disque didermique est composé du plafond de la cavité amniotique et du plancher de la vésicule vitelline","c":"c’est l’inverse !","s":"ANNALE Épreuve terminale 2024-2025 Q6"},{"f":"L’espace situé entre l’épiblaste et l’hypoblaste va être colonisé par des cellules entoblastiques","c":"Par des cellules mésoblastiques","s":"ANNALE Épreuve terminale 2022-2023 Q23"}]},{"name":"Lécithocèle secondaire (vésicule vitelline définitive)","facts":[{"t":"Le canal chordal établit la communication la cavité amniotique et le lécithocèle secondaire à J16 avant d’évoluer en canal neurentérique en J17 qui va également assurer cette communication.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Les îlots de Wolff et Pander (îlots angio-formateurs) apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline à J18 puis dans le chorion à partir de J22, mais jamais dans la somatopleure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"t":"Les premiers foyers angioformateurs, apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline","s":"ANNALE Épreuve terminale 2022-2023 Q31"},{"t":"Le canal chordal puis le canal neurentérique établissent une communication entre la cavité amniotique et le lécithocèle secondaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}],"pieges":[{"f":"Le 5 représente le lécithocèle secondaire.","c":"Il s’agit de la cavité amniotique.","s":"ANNALE Contrôle continu 2024-2025 Q12"},{"f":"Le disque didermique est composé du plafond de la cavité amniotique et du plancher de la vésicule vitelline","c":"c’est l’inverse !","s":"ANNALE Épreuve terminale 2024-2025 Q6"}]},{"name":"Cœlome extra-embryonnaire (cœlome externe)","facts":[{"t":"Le mésenchyme extra-embryonnaire régresse partiellement par apoptose, ce qui forme le cœlome extra-embryonnaire fin J13.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"À partir de J11–J13, le mésenchyme extra-embryonnaire (magma réticulé) se résorbe, formant le cœlome externe et trois lames mésenchymateuses : choriale, vitelline, amniotique.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Le 4 représente le cœlome extra embryonnaire.","s":"ANNALE Contrôle continu 2024-2025 Q12"},{"t":"Le trophoblaste se transforme en cytotrophoblaste entre le syncytiotrophoblaste et le cœlome extra embryonnaire","s":"ANNALE CC Embryologie 2023-2024 Q12"}],"pieges":[{"f":"Les chambres intervilleuses sont situées au sein du cœlome extra-embryonnaire","c":"Au sein du syncytiotrophoblaste","s":"ANNALE Rattrapage 2022-2023 Q4"},{"f":"Il y a une réduction importante du cœlome interne jusqu’à sa disparition","c":"Du coelome externe, attention ++ point de cours important","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Syncytiotrophoblaste","facts":[{"t":"Vers J10, l’œuf est entièrement implanté dans l’endomètre et du sang maternel est présent dans le syncytiotrophoblaste.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Les lacunes du syncytiotrophoblaste (qui ne sont PAS bordées par un épithélium) commencent en effet à se remplir de sang vers J10.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Dès J8, le trophoblaste se différencie en syncytiotrophoblaste (invasif) et cytotrophoblaste (couche cellulaire unique).","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Le trophoblaste se transforme en syncytiotrophoblaste en périphérie au contact de l'endomètre","s":"ANNALE CC Embryologie 2023-2024 Q12"}],"pieges":[{"f":"Les villosités primaires sont constituées par les cellules du syncytiotrophoblaste","c":"Du cytotrophoblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"f":"Les lacunes du syncytiotrophoblaste sont bordées par un endothélium.","c":"Les lacunes du syncytiotrophoblaste ne sont justement PAS bordées par un endothélium. Ce détail est important à retenir !","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"}]},{"name":"Cytotrophoblaste","facts":[{"t":"Dès J8, le trophoblaste se différencie en syncytiotrophoblaste (invasif) et cytotrophoblaste (couche cellulaire unique).","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"Le trophoblaste se transforme en cytotrophoblaste entre le syncytiotrophoblaste et le cœlome extra embryonnaire","s":"ANNALE CC Embryologie 2023-2024 Q12"},{"t":"Le trophoblaste se différencie en syncytiotrophoblaste et en cytotrophoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q6"},{"t":"Lors de la mise en place des villosités, le cytotrophoblaste est incorporé au sein des villosités secondaires.","s":"ANNALE Rattrapage 2023-2024 Q1"}],"pieges":[{"f":"Au cours de la nidation, le cytotrophoblaste permet la pénétration de l’endomètre","c":"C’est le syncytiotrophoblaste qui permet la pénétration dans l’endomètre.","s":"ANNALE Rattrapage 2022-2023 Q3"},{"f":"Les villosités primaires sont constituées par les cellules du syncytiotrophoblaste","c":"Du cytotrophoblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"}]},{"name":"Mésenchyme extra-embryonnaire (magma réticulé)","facts":[{"t":"A partir de J18 du développement embryonnaire, le mésenchyme extra-embryonnaire provenant de la lame choriale va se différencier en angioblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"La cavité amniotique se forme en même temps qu’apparaît du mésenchyme extra-embryonnaire (J8)","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"Le mésenchyme extra-embryonnaire se résorbe partiellement à partir de J11 en laissant trois lames mésenchymateuses : la lame choriale, la lame vitelline et la lame amniotique.","s":"ANNALE Rattrapage 2023-2024 Q9"},{"t":"La cavité amniotique se forme à J8, tout comme le mésenchyme extra-embryonnaire (autrement appelé magma réticulé).","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"}],"pieges":[{"f":"Le mésenchyme extra embryonnaire se résorbe partiellement à partir de J11 en laissant trois lames mésenchymateuses : la lame choriale, la lame vitelline et la lame amniotique.","c":"C’est à J13, attention aux dates !!!","s":"ANNALE Épreuve terminale 2023-2024 QEmbryologie-6 [2ème semaine]"},{"f":"La présence du blastocèle est concomitante à la présence du mésenchyme extra-embryonnaire.","c":"Le blastocèle apparaît à J5. Le mésenchyme extra-embryonnaire apparaît à J8.","s":"BANQUE Deuxième semaine du développement Concours blanc 3 – 2019/2020 Q17"}]},{"name":"Lacunes du syncytiotrophoblaste / réseau lacunaire","facts":[{"t":"Les lacunes du syncytiotrophoblaste (qui ne sont PAS bordées par un épithélium) commencent en effet à se remplir de sang vers J10.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Les lacunes du syncytiotrophoblaste ne sont justement PAS bordées par un endothélium.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Les lacunes ne sont pas remplies de sang à J9.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q43"},{"t":"Le sang maternel apparaît dans les lacunes un peu plus tard dans la semaine : à J10- J11.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q60"}],"pieges":[{"f":"Les lacunes du syncytiotrophoblaste sont bordées par un endothélium.","c":"Les lacunes du syncytiotrophoblaste ne sont justement PAS bordées par un endothélium. Ce détail est important à retenir !","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"f":"Les chambres intervilleuses sont situées au sein du cœlome extra-embryonnaire","c":"Au sein du syncytiotrophoblaste","s":"ANNALE Rattrapage 2022-2023 Q4"}]},{"name":"Lécithocèle primaire / membrane de Heuser","facts":[{"t":"La membrane de Heuser est cellulaire et ferme le lécithocèle primaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"Le lécithocèle secondaire se forme par bourgeonnement du lécithocèle primaire à J11-J13.","s":"BANQUE Deuxième semaine du développement Concours blanc 2 – 2019/2020 Q19"},{"t":"La formation du lécithocèle secondaire entre J10-J13 s’accompagne d’une disparition de la membrane de Heuser.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q45"},{"t":"Le lécithocèle primaire se forme à J9 et sera fermé par une membrane fine cellulaire : la membrane de Heuser.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q49"}],"pieges":[{"f":"Les évènements de la formation de la cavité amniotique (J8) du lécithocèle primaire et du signe de Hartmann sont contemporains.","c":"Attention la chronologie est importante en embryo ! La formation du lécithocèle primaire a lieu à J9 alors que le signe de Hartmann (donc la fermeture de la brèche épithéliale par un caillot séro-fibrineux) a lieu à J10.","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2020/2021 Q11"},{"f":"La formation du lécithocèle primaire et celle de la cavité amniotique ont lieu en même temps.","c":"La cavité amniotique se forme à J8. Le lécithocèle primaire se forme à J9.","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2019/2020 Q25"}]},{"name":"Jumeaux (chorialité / amnioticité)","facts":[{"t":"Environ 70% des grossesses gémellaires sont des grossesses bichoriales biamniotiques.","s":"ANNALE Rattrapage 2022-2023 Q3"},{"t":"25-30% sont monochoriales biamniotiques et environ 3% sont monochoriales monoamniotiques.","s":"ANNALE Rattrapage 2022-2023 Q3"},{"t":"Une division de la masse cellulaire interne d’un blastocyste aboutit à la constitution de jumeaux monochoriaux diamniotiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"On obtiendra donc des jumeaux monochoriaux diamniotiques (dans le même placenta mais avec des cavités amniotiques séparées.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"}],"pieges":[{"f":"Les jumeaux monozygotes dichoriaux diamniotiques sont le type de jumeaux monozygotes le plus fréquent. Épreuve majeure 2 – 2020/2021","c":"Ce sont les jumeaux monozygotes MONOchoriaux et DIamniotiques. Épreuve majeure 2 – 2020-2021","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2020/2021 Q10"},{"f":"Des jumeaux monozygotes sont obligatoirement monochoriaux. Epreuve majeure 2 – 2019/2020","c":"Des jumeaux monozygotes peuvent aussi être dichoriaux, si leur séparation a lieu au stade de la morula ou avant. Epreuve majeure 2 – 2019/2020","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2019/2020 Q25"}]},{"name":"hCG","facts":[{"t":"L’HCG peut être détectée dans le sang à partir de J10 et dans les urines dès J11.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"On peut donc doser l’HCG à partir de J25-J26 du cycle maternel, soit quelques jours avant la fin du cycle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"L’HCG peut être détectée dans le sang et les urines maternels quelques jours avant la fin du cycle maternel.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q21"},{"t":"Dès J10 du développement embryonnaire, un dosage sanguin de β-hCG est possible.","s":"BANQUE Deuxième semaine du développement Concours blanc 1 – 2019/2020 Q21"}],"pieges":[{"f":"L’hCG est détectable au même moment dans le sang et les urines.","c":"C’est le CT et le SCT qui sécrètent l’hCG dès le début de l’implantation mais elle devient significative au milieu de la 2ème semaine. On peut faire un dosage sanguin maternel dès J10/J11 alors qu’il faudra attendre J11/J12 pour le test urinaire.","s":"BANQUE Deuxième semaine du développement Concours blanc PASS – 2020/2021 Q2"},{"f":"L’hCG est détectable dans le dosage sanguin maternel et dans le test urinaire le même jour.","c":"Il est détectable dans le dosage sanguin à J10 et à J11 dans le test urinaire.","s":"BANQUE Deuxième semaine du développement Concours blanc 2 – 2017/2018 Q35"}]}]},{"week":3,"stages":[{"day":"J14-J15","label":"Ligne primitive et nœud de Hensen dans l'épiblaste","events":[{"t":"La ligne primitive se forme entre J14-15.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q20"},{"t":"À J14, une ligne délimitée par le nœud de Hensen et le nœud postérieur se creuse dans l’ectoblaste.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q46"},{"t":"Le nœud de Hensen et le nœud postérieur sont formés au moment de la ligne primitive soit J14-J15 et ils subsistent encore tout au long de la troisième semaine.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q49"},{"t":"La ligne primitive se met en place dans le pôle caudal de l’embryon","s":"ANNALE Épreuve terminale 2022-2023 Q22"}]},{"day":"J16","label":"Ingression : processus chordal / canal chordal, plaque préchordale, allantoïde","events":[{"t":"À J16, des cellules épiblastiques migrent et s’infiltrent au travers du nœud de Hensen, il y a ainsi formation du canal chordal.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2014/2015 Q61"},{"t":"La plaque préchordale peut être observée à partir de J16.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q49"},{"t":"L’allantoïde se forme à J16, le canal chordal évolue en canal neurentérique à J17 et la zone cardiogène se forme à J18.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q18"}]},{"day":"J17","label":"Plaque chordale et canal neurentérique","events":[{"t":"A J17, le canal chordal évolue en canal neurentérique qui se fermera autour de J22.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2017/2018 Q35"},{"t":"La plaque chordale et le canal neurentérique peuvent être observés à J17.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q48"},{"t":"Le canal chordal établit la communication la cavité amniotique et le lécithocèle secondaire à J16 avant d’évoluer en canal neurentérique en J17 qui va également assurer cette communication.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}]},{"day":"J18","label":"Fin de la gastrulation, début des phénomènes post-gastrulaires (condensation du mésoblaste, plaque neurale)","events":[{"t":"A J18, la gastrulation est terminée et c’est le début des évènements post-gastrulaires.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2017/2018 Q35"},{"t":"Les évènements post-gastrulaires commencent à J18 avec la condensation du mésoblaste et le début de segmentation du mésoblaste para-axial.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2015/2016 Q53"},{"t":"La plaque neurale se forme à J18 entre la membrane pharyngienne et le nœud de Hensen, elle est donc en avant de la ligne primitive.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2018/2019 Q31"},{"t":"À J18, l’épiblaste devient l’ectoderme et l’hypoblaste devient l’endoderme.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2019/2020 Q17"},{"t":"À J18, l’endoblaste est constitué majoritairement de cellules mésoblastiques et minoritairement de cellules hypoblastiques.","s":"BANQUE Troisième semaine du développement Concours blanc n°1 – 2020/2021 Q9"},{"t":"La chorde provient du détachement de la plaque chordale de l’endoblaste, elle commence à se former à partir de J18.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2014/2015 Q61"},{"t":"Les cellules germinales primitives apparaissent aux alentours de l’allantoïde aussi à partir de J18.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"t":"Elle commence à J18 avec la formation de la plaque neurale, et à J22 on aura la formation du tube neural.","s":"BANQUE 4e semaine du développement embryonnaire Concours Blanc – 2015/2016 Q64"}]},{"day":"J19","label":"Gouttière neurale ; première paire de somitomères","events":[{"t":"À J19 on observe le passage du stade de plaque au stade de gouttière neurale grâce au changement de forme des cellules la constituant par resserrement de leur pôle apical.","s":"BANQUE Troisième semaine du développement Concours blanc n°1 – 2020/2021 Q13"},{"t":"Vers J19 apparaît la première paire, puis la deuxième.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q46"},{"t":"La plaque neurale existe à J18 avant de devenir la gouttière neurale à J19 alors que les paires de néphrotomes (= pronéphros) sont issues de la division du mésoblaste intermédiaire qui débute seulement à J20.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"}]},{"day":"J20","label":"Clivage de la lame latérale (somatopleure / splanchnopleure, cœlome interne), 7 paires de somitomères, pronéphros","events":[{"t":"La lame latérale se clive en deux feuillets qui se poursuivent respectivement par la lame amniotique et la lame vitelline à partir de J20.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2018/2019 Q29"},{"t":"Les 7 paires de somitomères sont toutes présentes à la fin de J20.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q46"},{"t":"L’ébauche du cœlome interne est bien visible à J20 avec le clivage de la lame latérale mais c’est visible sur une coupe transversale.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Le pronephros est une structure présente entre J20 et J25.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}]},{"day":"J16-J22","label":"Communication cavité amniotique – lécithocèle secondaire (canal chordal puis neurentérique)","events":[{"t":"En effet, la communication entre ces deux cavités est continue de J16 (formation du canal chordal) à J21-22 (disparition du canal neurentérique qui relait le canal chordal).","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q1"},{"t":"La cavité amniotique communique avec le lécithocèle secondaire jusqu’à environ J22.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2017/2018 Q40"}]}],"structs":[{"name":"Membranes pharyngienne et cloacale (zones didermiques)","facts":[{"t":"Les membranes cloacales et pharyngiennes basculent de 180 degrés","s":"ANNALE Épreuve terminale 2022-2023 Q26"},{"t":"Lors des délimitations céphalo-caudales de l’embryon, les membranes pharyngiennes et cloacales réalisent une bascule de 180 degrés.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"A la fin de la mise en place du troisième feuillet, deux régions du disque embryonnaire restent didermiques","s":"ANNALE Épreuve terminale 2022-2023 Q23"},{"t":"L’espace entre les 2 feuillets n’est pas colonisé au niveau de la membrane pharyngienne et de la membrane cloacale qui restent didermiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"}],"pieges":[{"f":"L’espace entre les 2 feuillets du disque didermique va être entièrement colonisé pour donner le chordo-mésoblaste.","c":"L’espace entre les 2 feuillets n’est pas colonisé au niveau de la membrane pharyngienne et de la membrane cloacale qui restent didermiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"},{"f":"La membrane pharyngienne se résorbe au début de la 4ème semaine.","c":"La membrane pharyngienne se résorbe entre J26 et J28, donc à la fin de la 4ème semaine.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 3 – 2019/2020 Q19"}]},{"name":"Cœur : zone cardiogène / tubes endocardiques / tube cardiaque","facts":[{"t":"à J24, les battements cardiaques sont propulsifs","s":"ANNALE Épreuve terminale 2024-2025 Q17"},{"t":"Les battements cardiaques n’ont une action propulsive qu’à partir de J24 avec des mouvements péristaltiques qui déterminent le sens du flux sanguin.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"t":"La fusion des tubes endocardiques se fait dans le sens crânio-caudal à partir de J20.","s":"ANNALE Rattrapage 2023-2024 Q6"},{"t":"les précurseurs cardiaques proviennent du mésoblaste latéral","s":"ANNALE Épreuve terminale 2024-2025 Q17"}],"pieges":[{"f":"Les battements cardiaques ont une action propulsive à partir de J18 avec des mouvements péristaltiques qui déterminent le sens du flux sanguin.","c":"Les battements cardiaques n’ont une action propulsive qu’à partir de J24 avec des mouvements péristaltiques qui déterminent le sens du flux sanguin.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"f":"La fusion des tubes endocardiques est réalisée dans le sens caudo-cranial.","c":"La fusion des tubes endocardiques se fait dans le sens crânio-caudal à partir de J20.","s":"ANNALE Rattrapage 2023-2024 Q6"}]},{"name":"Somatopleure / splanchnopleure","facts":[{"t":"Les îlots de Wolff et Pander (îlots angio-formateurs) apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline à J18 puis dans le chorion à partir de J22, mais jamais dans la somatopleure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"t":"le péricarde pariétal provient de la somatopleure","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"Les précurseurs cardiaques proviennent de la splanchnopleure","s":"ANNALE Rattrapage 2023-2024 Q3"},{"t":"Du mésoblaste latéral avec la splanchnopleure plutôt","s":"ANNALE Épreuve terminale 2022-2023 Q31"}],"pieges":[{"f":"Les foyers angioformateurs (Ilots de Wolff et Pander) apparaissent, entre autres, dans la somatopleure.","c":"Les îlots de Wolff et Pander (îlots angio-formateurs) apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline à J18 puis dans le chorion à partir de J22, mais jamais dans la somatopleure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"f":"La somatopleure correspond à la lame située proche de l’entoblaste","c":"Elle est proche de l’ectoblaste.","s":"ANNALE Rattrapage 2023-2024 Q2"}]},{"name":"Gastrulation (généralités, chordés)","facts":[{"t":"suite à la gastrulation, le disque embryonnaire possède une organisation dorso-ventrale","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"Toutes anomalies ayant lieu avant la gastrulation peut conduire directement à la mort de l‘ embryon, c'est une réaction dite en «tout ou rien»","s":"ANNALE Épreuve terminale 2022-2023 Q22"},{"t":"Au cours de la gastrulation, des cellules épiblastiques vont se détacher et migrer à travers la ligne primitive, et subissent une transformation épithélio-mésenchymateuse.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"},{"t":"La gastrulation permet la mise en place du chordo-mésoblaste","s":"ANNALE Rattrapage 2022-2023 Q4"}],"pieges":[{"f":"la gastrulation ne concerne qu’un sous-groupe des chordées","c":"c’est justement tous les chordés qui subissent la gastrulation","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"f":"Le phénomène de gastrulation ne s’observe que chez les mammifères.","c":"Le phénomène de gastrulation s’observe chez tous les chordés, embranchement dont les mammifères font partie. Ainsi, la gastrulation s’observe chez tous les mammifères mais pas que chez les mammifères.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"}]},{"name":"Mésoblaste (axial, para-axial, intermédiaire, latéral)","facts":[{"t":"A la fin de la segmentation du mésoblaste para-axial, il y a 5 paires de somites lombaires.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"la segmentation du mésoblaste intermédiaire est incomplète","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"t":"les précurseurs cardiaques proviennent du mésoblaste latéral","s":"ANNALE Épreuve terminale 2024-2025 Q17"},{"t":"Au sein de celui-ci, il existe un domaine axial","s":"ANNALE Épreuve terminale 2022-2023 Q24"}],"pieges":[{"f":"La segmentation du mésoblaste intermédiaire est complète","c":"1 paire de néphrotomes par somite jusqu’à la 4e paire de somite lombaire.","s":"ANNALE Épreuve terminale 2022-2023 Q28"},{"f":"la molécule Bone Morphogenetic Protein 4 (BMP-4) est nécessaire pour la mise en place du mésoblaste latérale","c":"il sert surtout à inhiber la neurulation à la périphérie de l’éctoblaste : il est épidermisant.","s":"ANNALE Épreuve terminale 2024-2025 Q11"}]},{"name":"Ligne primitive","facts":[{"t":"le gène NODAL intervient dans la mise en place de la ligne primitive","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"t":"les siamois peuvent être originaires d’un dédoublement partiel de la ligne primitive","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"t":"le bourgeon caudal est issu de la ligne primitive","s":"ANNALE Épreuve terminale 2024-2025 Q12"},{"t":"La ligne primitive se met en place dans le pôle caudal de l’embryon","s":"ANNALE Épreuve terminale 2022-2023 Q22"}],"pieges":[{"f":"la ligne primitive se met en place dans l’entoblaste","c":"dans l’ectoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"f":"la molécule Bone Morphogenetic Protein 4 (BMP-4) est secrétée par les cellules situées dans la partie céphalique de la ligne primitive","c":"au niveau du nœud postérieur (partie caudale)","s":"ANNALE Épreuve terminale 2024-2025 Q11"}]},{"name":"Chordo-mésoblaste / troisième feuillet / entoblaste définitif","facts":[{"t":"L’hypoblaste prend le nom d’endoblaste à la 3ème semaine après la mise en place du 3ème feuillet à J18.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"le canal chordal s’accole progressivement à l’entoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"A la fin de la mise en place du troisième feuillet, deux régions du disque embryonnaire restent didermiques","s":"ANNALE Épreuve terminale 2022-2023 Q23"},{"t":"L’endoblaste dérive de l’hypoblaste et est constitué majoritairement de cellules mésoblastiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}],"pieges":[{"f":"la ligne primitive se met en place dans l’entoblaste","c":"dans l’ectoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"f":"L’espace entre les 2 feuillets du disque didermique va être entièrement colonisé pour donner le chordo-mésoblaste.","c":"L’espace entre les 2 feuillets n’est pas colonisé au niveau de la membrane pharyngienne et de la membrane cloacale qui restent didermiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"}]},{"name":"Lame latérale / clivage (cœlome intra-embryonnaire)","facts":[{"t":"L’ébauche du cœlome interne est bien visible à J20 avec le clivage de la lame latérale mais c’est visible sur une coupe transversale.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Au cours de la 4ème semaine, le coelome intra-embryonnaire se développe tandis que le coelome extra-embryonnaire se réduit.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"La lame latérale provient du clivage du mésoblaste latéral","s":"ANNALE Rattrapage 2022-2023 Q6"},{"t":"Le cœlome interne lui se développe.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"À J 20, on peut voir l’ébauche du coelome interne sur une coupe sagittale.","c":"Attention ! L’ébauche du cœlome interne est bien visible à J20 avec le clivage de la lame latérale mais c’est visible sur une coupe transversale.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"f":"Il y a une réduction importante du cœlome interne jusqu’à sa disparition","c":"Du coelome externe, attention ++ point de cours important","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Chorde dorsale","facts":[{"t":"la chorde dorsale provient de la plaque chordale","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"La neurulation primaire débute par un épaississement d’une partie de l’ectoblaste sous l’effet inducteur de la chorde","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"La formation d’une vertèbre est induite par la chorde et par le tube neural.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"La chorde induit la formation du corps vertébral et le tube neural induit la formation des arcs vertébraux.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"les reliquats embryonnaires de la chorde se nomment les nucleus chordori","c":"ces fragments sont appelés nucléus pulposus, de plus ce QCM concerne la segmentation du mésoblaste para-axiale, la chorde fait partie de mésoblaste axial.","s":"ANNALE Épreuve terminale 2024-2025 Q14"},{"f":"La formation d’une vertèbre est induite exclusivement par la chorde.","c":"La formation d’une vertèbre est induite par la chorde et par le tube neural. La chorde induit la formation du corps vertébral et le tube neural induit la formation des arcs vertébraux.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}]},{"name":"Angiogenèse / îlots de Wolff et Pander / foyers angioformateurs","facts":[{"t":"A partir de J18 du développement embryonnaire, le mésenchyme extra-embryonnaire provenant de la lame choriale va se différencier en angioblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"Les îlots de Wolff et Pander (îlots angio-formateurs) apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline à J18 puis dans le chorion à partir de J22, mais jamais dans la somatopleure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"t":"La condensation des précurseurs cardiaques au sein de la zone cardiogène va donner naissance aux cordons angioblastiques","s":"ANNALE Épreuve terminale 2022-2023 Q31"},{"t":"Les premiers foyers angioformateurs, apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline","s":"ANNALE Épreuve terminale 2022-2023 Q31"}],"pieges":[{"f":"Les foyers angioformateurs (Ilots de Wolff et Pander) apparaissent, entre autres, dans la somatopleure.","c":"Les îlots de Wolff et Pander (îlots angio-formateurs) apparaissent dans le mésoblaste splanchnopleural de la vésicule vitelline à J18 puis dans le chorion à partir de J22, mais jamais dans la somatopleure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"f":"Les angioblastes proviennent de la lame amniotique.","c":"justement la lame amniotique ne comprend aucun angioblaste","s":"ANNALE Épreuve terminale 2024-2025 Q7"}]},{"name":"Allantoïde (diverticule allantoïdien)","facts":[{"t":"la délimitation permet l’incorporation d’une partie du diverticule allantoïdien","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"t":"Les cellules germinales primitives qui apparaissent dans la région de l’allantoïde à J18 sont d’origine ectoblastique.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"t":"A partir de J26, le canal de Wolff s’abouche à la face postérieure de l’allantoïde.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q31"},{"t":"À J22, l’allantoïde est incorporée à l’embryon et dans le même temps le canal neurentérique disparaît.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2015/2016 Q67"}],"pieges":[{"f":"la plaque préchordale est située à proximité de l’allantoïde","c":"elle est située en position céphalique","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"f":"Le diverticule allantoïdien est complétement incorporé dans l’embryon","c":"Il devient partiellement intra-embryonnaire","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Feuillets définitifs (ectoblaste, mésoblaste, endoblaste)","facts":[{"t":"La neurulation primaire débute par un épaississement d’une partie de l’ectoblaste sous l’effet inducteur de la chorde","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"Elle est proche de l’ectoblaste.","s":"ANNALE Rattrapage 2023-2024 Q2"},{"t":"Le tube neural se forme à partir de la gouttière neurale fin J21 et est entièrement issu du neurectoblaste.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"t":"À J25-J26, dans la région des membranes pharyngienne et cloacale, l’endoblaste est au-dessus de l’ectoblaste.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q59"}],"pieges":[{"f":"la ligne primitive se met en place dans l’entoblaste","c":"dans l’ectoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"f":"La somatopleure correspond à la lame située proche de l’entoblaste","c":"Elle est proche de l’ectoblaste.","s":"ANNALE Rattrapage 2023-2024 Q2"}]},{"name":"Segmentation du mésoblaste para-axial / somitomères","facts":[{"t":"A la fin de la segmentation du mésoblaste para-axial, il y a 5 paires de somites lombaires.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"le disque tridermique correspond à un empilement de métamères","s":"ANNALE Épreuve terminale 2024-2025 Q12"},{"t":"la segmentation du mésoblaste intermédiaire est incomplète","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"t":"Le début de segmentation du mésoblaste para-axial est contemporain de la formation de la plaque neurale","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"}],"pieges":[{"f":"La segmentation du mésoblaste intermédiaire est complète","c":"1 paire de néphrotomes par somite jusqu’à la 4e paire de somite lombaire.","s":"ANNALE Épreuve terminale 2022-2023 Q28"},{"f":"les reliquats embryonnaires de la chorde se nomment les nucleus chordori","c":"ces fragments sont appelés nucléus pulposus, de plus ce QCM concerne la segmentation du mésoblaste para-axiale, la chorde fait partie de mésoblaste axial.","s":"ANNALE Épreuve terminale 2024-2025 Q14"}]},{"name":"Cordon ombilical / pédicule embryonnaire","facts":[{"t":"Cette résorption n’est pas totale et laisse plusieurs couches cellulaires (lame choriale, lame amniotique, lame vitelline et pédicule embryonnaire.)","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"Le pédicule embryonnaire à J13 sur une coupe sagittale.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q53"},{"t":"Les vaisseaux ombilicaux sont les vaisseaux qui se sont développés dans le pédicule embryonnaire à partir des îlots vasculo-sanguins primitifs de Wolff et Pander à partir de J18.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"t":"La délimitation permet la mise en place du cordon ombilical.","s":"ANNALE Épreuve terminale 2023-2024 QEmbryologie-12 [Délimitation et neurulation]"}],"pieges":[{"f":"La plicature de l’embryon entraine l’intégration de la vésicule vitelline au pédicule embryonnaire, cette structure prendra plus tard le nom de cordon ombilical.","c":"L’intégration de la vésicule vitelline (alors très diminuée) au pédicule embryonnaire n’aura lieu qu’à la 7e semaine de développement et ce moment-là que cette structure prend le nom de cordon ombilical.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q2"},{"f":"On peut de plus dire qu’à la fin de cette semaine, le cordon ombilical est formé.","c":"le cordon ombilical ne va se former qu’à la fin de la 6ème semaine au moment où le sac vitellin régresse et s’incorpore au pédicule embryonnaire.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2015/2016 Q68"}]},{"name":"Nœud de Hensen (nœud antérieur / postérieur)","facts":[{"t":"le canal neurentérique provient du nœud antérieur","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"au niveau du nœud postérieur (partie caudale)","s":"ANNALE Épreuve terminale 2024-2025 Q11"},{"t":"Non, c’est le nœud antérieur de la LP","s":"ANNALE Épreuve terminale 2022-2023 Q22"},{"t":"La distribution asymétrique des organes est faite par les cellules ciliées au niveau du nœud de Hensen. Epreuve majeure 2 – 2018/2019","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2018/2019 Q30"}],"pieges":[{"f":"Le nœud postérieur de la ligne primitive se nomme le nœud de Hensen","c":"Non, c’est le nœud antérieur de la LP","s":"ANNALE Épreuve terminale 2022-2023 Q22"},{"f":"la molécule Bone Morphogenetic Protein 4 (BMP-4) est secrétée par les cellules situées dans la partie céphalique de la ligne primitive","c":"au niveau du nœud postérieur (partie caudale)","s":"ANNALE Épreuve terminale 2024-2025 Q11"}]},{"name":"Villosités choriales (primaires, secondaires, tertiaires)","facts":[{"t":"Les villosités primaires sont situées tout autour de l’œuf.","s":"ANNALE Épreuve terminale 2024-2025 Q7"},{"t":"Le centre des colonnes des villosités secondaires est constitué par des cellules mésenchymateuses","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"Les villosités tertiaires sont localisées sur la totalité de la surface de la lame choriale","s":"ANNALE Épreuve terminale 2022-2023 Q21"},{"t":"Concernant la formation du placenta diffus, les villosités tertiaires correspondent à une néoformation de vaisseaux dans le mésenchyme des villosités.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"}],"pieges":[{"f":"Les villosités crampons sont des villosités secondaires.","c":"villosités tertiaires","s":"ANNALE Épreuve terminale 2024-2025 Q7"},{"f":"Les villosités primaires sont constituées par les cellules du syncytiotrophoblaste","c":"Du cytotrophoblaste","s":"ANNALE Épreuve terminale 2022-2023 Q21"}]},{"name":"Canal neurentérique","facts":[{"t":"Le canal chordal établit la communication la cavité amniotique et le lécithocèle secondaire à J16 avant d’évoluer en canal neurentérique en J17 qui va également assurer cette communication.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"le canal neurentérique provient du nœud antérieur","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"Le canal chordal puis le canal neurentérique établissent une communication entre la cavité amniotique et le lécithocèle secondaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"La chorde est totalement détachée à J22, entraînant la fermeture du canal neurentérique.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q30"}],"pieges":[{"f":"Dès le début de la 4ème semaine, la chorde est entièrement détachée et formée, au même titre que le canal neurentérique.","c":"la chorde est entièrement détachée à J22, cela se fait au moment où le canal neurentérique est résorbé. Et c’est aussi à ce moment-là que la gouttière neurale est fermée (fin J21 - début J22) formant ainsi le tube neural.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2015/2016 Q69"},{"f":"Le canal chordal constitue une évolution du canal neurentérique.","c":"C’est l’inverse : le canal chordal est l’évolution du canal neurentérique à J17, lorsque la plaque chordale s’accole à l’hypoderme.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q23"}]},{"name":"Canal chordal","facts":[{"t":"Le canal chordal établit la communication la cavité amniotique et le lécithocèle secondaire à J16 avant d’évoluer en canal neurentérique en J17 qui va également assurer cette communication.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"le canal chordal s’accole progressivement à l’entoblaste","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"Le canal chordal puis le canal neurentérique établissent une communication entre la cavité amniotique et le lécithocèle secondaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"À J16, des cellules épiblastiques migrent et s’infiltrent au travers du nœud de Hensen, il y a ainsi formation du canal chordal.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2014/2015 Q61"}],"pieges":[{"f":"La structure 1 représente le canal chordal.","c":"Item d’annale ! On voit sur cette vue que la chorde a commencé à se former, on se situe donc après J18 date à laquelle la plaque chordale commence à se détacher ; or le canal neurentérique relait le canal chordal à partir de J18. La structure 1 est donc le canal neurentérique et non pas chordal.","s":"BANQUE Troisième semaine du développement Concours Blanc n°2 – 2020/2021 Q8"},{"f":"Le canal chordal constitue une évolution du canal neurentérique.","c":"C’est l’inverse : le canal chordal est l’évolution du canal neurentérique à J17, lorsque la plaque chordale s’accole à l’hypoderme.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q23"}]},{"name":"Gouttière neurale / bourrelets neuraux","facts":[{"t":"La deuxième étape de la neurulation primaire correspond à la fusion des bords de la gouttière neurale","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"La fermeture de la gouttière neurale pour former le tube neural s’effectue de manière bidirectionnelle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"t":"Le tube neural se forme à partir de la gouttière neurale fin J21 et est entièrement issu du neurectoblaste.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"t":"Dès la fin de J21, la neurulation primaire s’initie avec la fusion des bords latéraux de la gouttière neurale dans la région des 4e et 5e paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2014/2015 Q77"}],"pieges":[{"f":"Les cellules des crêtes neurales correspondent à des cellules du fond de la gouttière neurale qui se sont détachées et qui migrent à l’extérieur","c":"Sur les bords de la gouttière neurale et pas au fond.","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"f":"Le tube neural se forme à partir de la gouttière neurale d’avant en arrière.","c":"Attention, piège ultra récurrent !!!! La fermeture de la gouttière neurale pour former le tube neural s’effectue de manière bidirectionnelle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}]},{"name":"Sinus veineux / veines (vitellines, ombilicales, cardinales)","facts":[{"t":"Le sinus veineux reçoit à la fois le sang oxygéné et le sang pauvre en oxygène.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q27"},{"t":"Les veines vitellines se jettent dans le sinus veineux.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q28"},{"t":"On distingue généralement 5 renflements : truncus arteriosus, bulbe artériel, ventricule primitif, oreillette primitive, sinus veineux.","s":"ANNALE Rattrapage 2023-2024 Q6"},{"t":"Les veines vitellines ne rejoignent pas les veines cardinales communes mais se drainent dans le sinus veineux cardiaque, tout comme les veines cardinales.","s":"ANNALE Rattrapage 2023-2024 Q6"}],"pieges":[{"f":"Les veines vitellines se jettent dans les veines cardinales communes.","c":"Les veines vitellines se jettent dans le sinus veineux.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q28"},{"f":"Les deux veines vitellines rejoignent les veines cardinales communes.","c":"Les veines vitellines ne rejoignent pas les veines cardinales communes mais se drainent dans le sinus veineux cardiaque, tout comme les veines cardinales.","s":"ANNALE Rattrapage 2023-2024 Q6"}]},{"name":"Plaque neurale","facts":[{"t":"Le début de segmentation du mésoblaste para-axial est contemporain de la formation de la plaque neurale","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"L’ectoblaste se condense en plaque neurale vers J18.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2013/2014 Q63"},{"t":"La plaque neurale existe à J18 avant de devenir la gouttière neurale à J19 alors que les paires de néphrotomes (= pronéphros) sont issues de la division du mésoblaste intermédiaire qui débute seulement à J20.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"t":"L’élément B représente la plaque neurale qui correspond bien à la première manifestion de la neurulation et se forme à J18.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q22"}],"pieges":[{"f":"La plaque neurale et les premières paires de néphrotomes.","c":"La plaque neurale existe à J18 avant de devenir la gouttière neurale à J19 alors que les paires de néphrotomes (= pronéphros) sont issues de la division du mésoblaste intermédiaire qui débute seulement à J20.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"f":"La plaque neurale se forme entre le nœud de Hensen et le nœud postérieure.","c":"La plaque neural se forme le nœud de Hensen et la membrane pharyngienne. Entre le nœud de Hensen et le nœud postérieure se trouve la ligne primitive. (Schéma en vue du dessus représentant la mise en place de la plaque neurale à J18).","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q18"}]},{"name":"Ingression / EMT / cadhérines / FGF8","facts":[{"t":"l’épibolie correspond au glissement d’une nappe cellulaire","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"t":"la migration des cellules entre les deux feuillets adopte la forme d’un chandelier","s":"ANNALE Épreuve terminale 2024-2025 Q9"},{"t":"FGF-8 est l’un des facteur contrôlant le mouvement des cellules","s":"ANNALE Épreuve terminale 2024-2025 Q9"},{"t":"La migration des cellules possède un aspect de chandelier","s":"ANNALE Épreuve terminale 2022-2023 Q23"}],"pieges":[{"f":"la transition épithélio-mésenchymateuse (EMT) correspond à l’acquisition de la E-","c":"Elles acquièrent de la N-cadhérine.","s":"ANNALE Épreuve terminale 2024-2025 Q9"},{"f":"Le mouvement des cellules à travers la ligne primitive et à l’intérieur du disque embryonnaire est appelée épibolie","c":"Attention, on parle d’ingression ici","s":"ANNALE Épreuve terminale 2022-2023 Q23"}]},{"name":"Gènes de la gastrulation (Nodal, BMP4, noggin, chordine, SHH)","facts":[{"t":"le gène NODAL intervient dans la mise en place de la ligne primitive","s":"ANNALE Épreuve terminale 2024-2025 Q8"},{"t":"la molécule sonic hedgehog (SHH) intervient dans la morphogenèse asymétrique","s":"ANNALE Épreuve terminale 2024-2025 Q11"},{"t":"Bone morphogenetic protein 4 (BMP4) est responsable de l'inhibition de la transformation des cellules ectodermiques en cellules neurales","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"BMP-4 (Bone morphogenetic Protein 4) est nécessaire pour la mise en place du mésoblaste latéral","s":"ANNALE Rattrapage 2022-2023 Q6"}],"pieges":[{"f":"la molécule Bone Morphogenetic Protein 4 (BMP-4) est secrétée par les cellules situées dans la partie céphalique de la ligne primitive","c":"au niveau du nœud postérieur (partie caudale)","s":"ANNALE Épreuve terminale 2024-2025 Q11"},{"f":"la molécule Bone Morphogenetic Protein 4 (BMP-4) est nécessaire pour la mise en place du mésoblaste latérale","c":"il sert surtout à inhiber la neurulation à la périphérie de l’éctoblaste : il est épidermisant.","s":"ANNALE Épreuve terminale 2024-2025 Q11"}]},{"name":"Barrière placentaire","facts":[{"t":"L’endothélium des vaisseaux est un des constituants de la barrière placentaire.","s":"ANNALE Épreuve terminale 2024-2025 Q7"},{"t":"La barrière placentaire à son origine est de 40 à 50 µm, alors qu’en fin de gestation elle n’est plus que de quelques µm, car les échanges sont de plus en plus importants.","s":"BANQUE Troisième semaine du développement Concours Blanc – 2015/2016 Q52"},{"t":"puisque l’œuf est totalement implanté dans l’endomètre à J10, la barrière placentaire apparaîtra plus tardivement à la fin de la 3e semaine.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q58"},{"t":"la ligne primitive se met en place vers J13-J14 alors que la barrière placentaire se met en place à partir de J18.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2019/2020 Q17"}],"pieges":[{"f":"L’implantation s’achève avec la constitution de la barrière placentaire.","c":"puisque l’œuf est totalement implanté dans l’endomètre à J10, la barrière placentaire apparaîtra plus tardivement à la fin de la 3e semaine.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q58"},{"f":"La formation de la ligne primitive coïncide avec la formation de la barrière placentaire.","c":"la ligne primitive se met en place vers J13-J14 alors que la barrière placentaire se met en place à partir de J18. Donc ces 2 événements ne coïncident pas.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2019/2020 Q17"}]},{"name":"Plaque chordale","facts":[{"t":"la chorde dorsale provient de la plaque chordale","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"La plaque chordale se détache d’avant en arrière et se détache totalement à J22.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2017/2018 Q35"},{"t":"La plaque chordale et le canal neurentérique peuvent être observés à J17.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q48"},{"t":"La plaque chordale et la ligne primitive à J18.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q49"}],"pieges":[{"f":"À J16, le canal préchordal va du nœud de Hensen à la plaque chordale.","c":"c’est le canal chordal qui va du nœud de Hensen à la plaque pré-chordale.","s":"BANQUE Deuxième semaine du développement Concours blanc – 2016/2017 Q47"},{"f":"La chorde se forme par détachement de la plaque chordale d’arrière en avant à partir de J18, ce détachement est complet à J22.","c":"Tout est vrai sauf que ce détachement se fait de l’avant vers l’arrière. Le canal neurentérique n’existe plus lorsque la chorde est totalement détachée.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2017/2018 Q41"}]},{"name":"Cellules germinales primordiales","facts":[{"t":"Les cellules germinales primitives qui apparaissent dans la région de l’allantoïde à J18 sont d’origine ectoblastique.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"t":"La formation de la zone cardiogène coïncide avec l’apparition des cellules germinales primordiales. Le schéma ci-dessous se rapporte aux questions 25 et 26.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2019/2020 Q24"},{"t":"Les cellules germinales primitives apparaissent aux alentours de l’allantoïde aussi à partir de J18.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"t":"Les cellules germinales primordiaux apparaissent bien à J18 par contre, les cellules germinales primordiales apparaissent en extra-embryonnaire.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2019/2020 Q16"}],"pieges":[{"f":"Les cellules germinales primitives se détachent de l’allantoïde à J18.","c":"Les cellules germinales apparaissent dans la région de l’allantoïde mais attention, les cellules germinales primitives ne dérivent absolument pas de l’allantoïde. L’allantoïde provient de l’endoblaste alors que les cellules germinales primitives dérivent de l’ectoblaste.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q3"},{"f":"Les cellules germinales primordiales apparaissent en position intra-embryonnaire à J18.","c":"Les cellules germinales primordiaux apparaissent bien à J18 par contre, les cellules germinales primordiales apparaissent en extra-embryonnaire. Coupe sagittale d’un embryon à la fin de la troisième semaine.","s":"BANQUE Troisième semaine du développement Concours blanc 2 – 2019/2020 Q16"}]},{"name":"Disque embryonnaire (polarité dorso-ventrale, axe céphalo-caudal, taille)","facts":[{"t":"À la fin de la deuxième semaine, le diamètre de l’œuf est 10 fois plus grand que le diamètre du disque.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"t":"suite à la gastrulation, le disque embryonnaire possède une organisation dorso-ventrale","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"t":"La ligne primitive possède un rôle dans la polarité dorso-ventrale","s":"ANNALE Épreuve terminale 2022-2023 Q22"},{"t":"A la fin de la mise en place du troisième feuillet, deux régions du disque embryonnaire restent didermiques","s":"ANNALE Épreuve terminale 2022-2023 Q23"}],"pieges":[{"f":"À la fin de la 2ème semaine, le diamètre du disque est environ la moitié du diamètre total de l’œuf.","c":"À la fin de la deuxième semaine, le diamètre de l’œuf est 10 fois plus grand que le diamètre du disque.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q22"},{"f":"la molécule noggin est nécessaire pour la formation de l’axe céphalo-caudal de l’embryon","c":"l’axe dorso-ventral","s":"ANNALE Épreuve terminale 2024-2025 Q11"}]},{"name":"Placenta diffus","facts":[{"t":"Le placenta diffus se met en place à partir du chorion de l’œuf.","s":"ANNALE Épreuve terminale 2024-2025 Q7"},{"t":"Concernant la formation du placenta diffus, les villosités tertiaires correspondent à une néoformation de vaisseaux dans le mésenchyme des villosités.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"},{"t":"L’allantoïde et les villosités secondaires du placenta diffus.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2017/2018 Q49"},{"t":"Les villosités primaires du placenta diffus et la ligne primitive.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2017/2018 Q49"}],"pieges":[{"f":"Le placenta diffus se met en place exclusivement à partir du syncytiotrophoblaste.","c":"A partir du SCT et du CT","s":"ANNALE Épreuve terminale 2023-2024 QEmbryologie-7 [Placenta et annexes]"}]},{"name":"Gènes homéotiques (Hox) / homéoboîte","facts":[{"t":"l’homéoboîte correspond à 180 nucléotides","s":"ANNALE Épreuve terminale 2024-2025 Q12"},{"t":"Un gène homéotique confirme une identité à un segment","s":"ANNALE Rattrapage 2023-2024 Q3"},{"t":"Une mutation portant sur un gène homéotique aura des conséquences gravissimes.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 2 – 2017/2018 Q44"},{"t":"Les gènes homéotiques possèdent des propriétés de colinéarité. La position des gènes sur le chromosome reflète leur domaine d’expression dans l’embryon.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc – 2016/2017 Q56"}],"pieges":[{"f":"l’homéodomaine est très peu conservé au cours de l’évolution","c":"il est conservé à 90 %","s":"ANNALE Épreuve terminale 2024-2025 Q12"},{"f":"Les gènes homéotiques se retrouvent uniquement chez les mammifères.","c":"Les gènes homéotiques permettent l’organisation d’un organisme. On les retrouve chez de nombreuses espèces différentes des mammifères comme les drosophiles par exemple.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc – 2016/2017 Q56"}]},{"name":"Induction neurale (chorde, BMP4, noggin)","facts":[{"t":"La neurulation primaire débute par un épaississement d’une partie de l’ectoblaste sous l’effet inducteur de la chorde","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"Certains agents inducteurs naturels peuvent avoir des effets tératogènes.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q27"},{"t":"Le tube neural est inducteur pour les arcs vertébraux.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2013/2014 Q85"},{"t":"La chorde est un puissant inducteur qui a un rôle dans la formation des vertèbres.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2019/2020 Q17"}],"pieges":[{"f":"La chorde est un inducteur de structures neuroblastiques seulement.","c":"C’est un inducteur de structures mésoblastiques et neuroblastiques.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 3 – 2019/2020 Q11"},{"f":"La chorde n’intervient pas dans la formation d’une vertèbre.","c":"La chorde est un puissant inducteur qui a un rôle dans la formation des vertèbres.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2019/2020 Q17"}]},{"name":"Plaque préchordale","facts":[{"t":"La plaque préchordale joue un rôle dans l’induction du cerveau antérieur","s":"ANNALE Rattrapage 2023-2024 Q2"},{"t":"La plaque préchordale peut être observée à partir de J16.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q49"},{"t":"La plaque préchordale et la plaque chordale.","s":"BANQUE Troisième semaine du développement Épreuve blanche – 2020/2021 Q2"},{"t":"Le nœud de Hensen, le nœud postérieur et la plaque préchordale.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q49"}],"pieges":[{"f":"la plaque préchordale est située à proximité de l’allantoïde","c":"elle est située en position céphalique","s":"ANNALE Épreuve terminale 2024-2025 Q10"},{"f":"À J16, le canal préchordal va du nœud de Hensen à la plaque chordale.","c":"c’est le canal chordal qui va du nœud de Hensen à la plaque préchordale. D. C’est le détachement de cette plaque chordale d’avant en arrière qui va former la chorde. →","s":"BANQUE Troisième semaine du développement Concours Blanc – 2015/2016 Q50"}]},{"name":"Bourgeon caudal / régression de la ligne primitive","facts":[{"t":"le bourgeon caudal est issu de la ligne primitive","s":"ANNALE Épreuve terminale 2024-2025 Q12"},{"t":"La neurulation secondaire fait intervenir le bourgeon caudal mésoblastique","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"Physiologiquement, elle forme d’abord le bourgeon caudal puis elle disparaît au cours de la 4ème semaine de développement embryonnaire.","s":"ANNALE Rattrapage 2022-2023 Q6"},{"t":"La ligne primitive régresse totalement","s":"ANNALE Rattrapage 2022-2023 Q6"}],"pieges":[{"f":"Le bourgeon caudal intervenant dans la neurulation secondaire est d’origine entoblastique","c":"D’origine mésoblastique","s":"ANNALE Rattrapage 2022-2023 Q8"},{"f":"La neurulation secondaire est réalisée avec de l’entoblaste.","c":"La neurulation secondaire se fait à partir du mésoblaste (bourgeon caudal mésoblastique), pas de l'entoblaste.","s":"ANNALE Rattrapage 2023-2024 Q5"}]},{"name":"Processus chordal (prolongement céphalique)","facts":[{"t":"le processus chordal est constitué de cellules ectoblastiques","s":"ANNALE Épreuve terminale 2024-2025 Q9"},{"t":"Le processus chordal est aussi appelé prolongement céphalique","s":"ANNALE Rattrapage 2023-2024 Q2"},{"t":"Le processus chordal est initialement une structure creuse","s":"ANNALE Rattrapage 2022-2023 Q5"}],"pieges":[]}]},{"week":4,"stages":[{"day":"J21-J22","label":"Fermeture de la gouttière neurale : tube neural (débute au niveau des 4e-5e paires de somites)","events":[{"t":"Dès la fin de J21, la neurulation primaire s’initie avec la fusion des bords latéraux de la gouttière neurale dans la région des 4e et 5e paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2014/2015 Q77"},{"t":"Le tube neural se forme au début de la 4e semaine, à J21-J22.","s":"BANQUE Troisième semaine du développement Concours blanc – 2016/2017 Q44"},{"t":"Il s’agit du tube neural, formé par la fermeture de la gouttière neurale entre J21 et J22.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q58"},{"t":"Les premières paires de somites définitifs apparaissent à J21, et on aura environ 25 paires à J28.","s":"BANQUE 4e semaine du développement embryonnaire Concours Blanc – 2015/2016 Q62"}]},{"day":"J22","label":"Chorde détachée, disparition du canal neurentérique, 1er arc branchial, gouttière respiratoire, début des plicatures (bascule 90°)","events":[{"t":"À J22, la chorde a fini de se détacher d’avant en arrière et se fragmente en reliquats embryonnaires qui peuvent être à l’origine de hernies discales.","s":"BANQUE 4e semaine du développement embryonnaire Concours Blanc – 2015/2016 Q62"},{"t":"À J22, l’allantoïde est incorporée à l’embryon et dans le même temps le canal neurentérique disparaît.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2015/2016 Q67"},{"t":"La première paire s’arcs se forme à J22, la deuxième paire à J24, la troisième paire à J26 et la 4ème paire à J28.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q25"},{"t":"La gouttière respiratoire apparaît à J22.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2017/2018 Q50"},{"t":"À J22, leur basculement est de 90° : les membranes se retrouvent dans un plan vertical.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q59"}]},{"day":"J24","label":"Fermeture du neuropore céphalique, flancs latéraux (≈20 paires de somites), 2e paire d'arcs, circulation embryonnaire","events":[{"t":"Le neuropore céphalique se ferme à J24 et le neuropore caudal se ferme à J26.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2014/2015 Q77"},{"t":"Les flancs latéraux apparaissent à J24, lorsqu’il y a environ 20 paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2– 2019/2020 Q24"},{"t":"La circulation intra-embryonnaire est effective à J24.","s":"BANQUE Mise en place de l’appareil circulatoire Épreuve majeure n°2 – 2014/2015 Q39"},{"t":"À J24, le lécithocèle est pratiquement fermé et donne ainsi naissance à l’intestin primitif.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2015/2016 Q68"}]},{"day":"J25","label":"Régression du pronéphros, fin de la paroi ventrale, bascule à 180° des membranes pharyngienne et cloacale","events":[{"t":"Le pronéphros a une durée de vie de 4 à 5 jours ainsi à J25 il disparait par régression.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q3"},{"t":"La paroi ventrale de l’embryon finit de se former à J25 cependant elle n’est jamais totalement fermée et reste ouverte au niveau de la vésicule vitelline qui est en communication avec l’intestin primitif.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q2"},{"t":"À J25-J26, dans la région des membranes pharyngienne et cloacale, l’endoblaste est au-dessus de l’ectoblaste.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q59"},{"t":"À J25-J26, ils ont encore basculé de 90°, donc leur basculement total est de 180° : les membranes se retrouvent dans un plan horizontal mais à l’envers par rapport à J21, avec l’ectoblaste en-dessous et l’endoblaste au-dessus.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q59"}]},{"day":"J26","label":"Fermeture du neuropore caudal, 3e arc, canal de Wolff s'abouche dans l'allantoïde, résorption de la membrane pharyngienne (J26-J28)","events":[{"t":"Le neuropore postérieur se ferme à J26, tandis que le neuropore antérieur s’est fermé deux jours plus tôt!","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2013/2014 Q87"},{"t":"Le 3 arc branchial apparaît à J26.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 3 – 2019/2020 Q13"},{"t":"Le canal de Wolff s’abouche à la face postérieure de l’allantoïde à J26.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 2 – 2019/2020 Q15"},{"t":"La membrane pharyngienne se résorbe bien entre J26 et J28 pour former la bouche primitive point de départ du tube digestif en revanche la membrane cloacale ne se résorbe pas encore.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2020/2021 Q6"}]},{"day":"J28","label":"4e arc, ≈25-30 paires de somites, ≈30 paires de tubules mésonéphrotiques, 5 arcs branchiaux internes, début du métanéphros","events":[{"t":"À J28, il y a 25 paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 3 – 2019/2020 Q11"},{"t":"À J28, il y a environ 30 paires de tubules mésonéphrotiques et 25 paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 2 – 2019/2020 Q15"},{"t":"À J28, l’appareil branchial est constitué intérieurement de 5 arcs branchiaux et 5 poches entobranchiales.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2016/2017 Q60"},{"t":"Le métanéphros apparaissant et se condensant entre J28 et J32 provient du mésoblaste.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"t":"La première paire s’arcs se forme à J22, la deuxième paire à J24, la troisième paire à J26 et la 4ème paire à J28.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q25"}]},{"day":"J30","label":"30 paires de somites définitifs","events":[{"t":"Il y a 30 paires de somites à J30.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 3 – 2019/2020 Q13"}]}],"structs":[{"name":"Tube neural (fermeture bidirectionnelle)","facts":[{"t":"l’allongement important du tube neural intervient dans la plicature céphalique","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"t":"La dorsalisation du toit du tube neural est faite par l'activation d'une cascade de facteurs de croissance de la famille des transforming growth factors-β (TGF)-β","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"Le rhombencéphale communique avec le tube médullaire primitif","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"L’allongement du tube neural représente l’événement majeur qui va aboutir à l’étranglement du lécithocèle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"Le tube neural ne possède qu’une ouverture : le neuropore postérieur","c":"ET le neuropore ANTERIEUR (2 ouvertures)","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"f":"Le tube neural se forme à partir de la gouttière neurale d’avant en arrière.","c":"Attention, piège ultra récurrent !!!! La fermeture de la gouttière neurale pour former le tube neural s’effectue de manière bidirectionnelle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}]},{"name":"Cloaque / membrane cloacale","facts":[{"t":"Les membranes cloacales et pharyngiennes basculent de 180 degrés","s":"ANNALE Épreuve terminale 2022-2023 Q26"},{"t":"Lors des délimitations céphalo-caudales de l’embryon, les membranes pharyngiennes et cloacales réalisent une bascule de 180 degrés.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"L’espace entre les 2 feuillets n’est pas colonisé au niveau de la membrane pharyngienne et de la membrane cloacale qui restent didermiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"},{"t":"L’allongement du tube neural entraîne une extension de la cavité amniotique et une bascule des membranes pharyngiennes et cloacales.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"L’espace entre les 2 feuillets du disque didermique va être entièrement colonisé pour donner le chordo-mésoblaste.","c":"L’espace entre les 2 feuillets n’est pas colonisé au niveau de la membrane pharyngienne et de la membrane cloacale qui restent didermiques.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q23"},{"f":"Les membranes pharyngienne et cloacales se résorbent en même temps.","c":"la membrane pharyngienne se résorbe entre J26 et J28 tandis que la membrane cloacale ne se résorbera que plus tard.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q31"}]},{"name":"Somites (paires, nombre)","facts":[{"t":"à la fin de la segmentation, il y a 7 paires de somites cervicaux","s":"ANNALE Épreuve terminale 2024-2025 Q14"},{"t":"La formation d’une vertèbre fait intervenir 2 paires de somites.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"A la fin de la segmentation du mésoblaste para-axial, il y a 5 paires de somites lombaires.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"1 paire de néphrotomes par somite jusqu’à la 4e paire de somite lombaire.","s":"ANNALE Épreuve terminale 2022-2023 Q28"}],"pieges":[{"f":"la zone externe du somite correspond au myotome","c":"la zone externe correspond au dermatome","s":"ANNALE Épreuve terminale 2024-2025 Q14"},{"f":"Le mésoblaste intermédiaire sera à l’origine des somites","c":"Il sera à l’origine des néphrotomes.","s":"ANNALE Épreuve terminale 2022-2023 Q24"}]},{"name":"Intestin primitif (antérieur, moyen, postérieur)","facts":[{"t":"l’intestin primitif antérieur correspond à la portion allant du pharynx à la portion D2 du duodénum","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"l’ébauche hépatique appartient à l’intestin primitif antérieur","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"t":"le caecum appartient à l’intestin primitif moyen","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"t":"Les 3 portions de l’intestin primitif sont définies en fonction de leurs vascularisations respectives.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}],"pieges":[{"f":"la totalité du colon appartient à l’intestin primitif postérieur","c":"Non la séparation IP moyen/postérieur se fait aux 2/3 du colon transverse.","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"f":"la formation du sac vitellin précède la plicature ventrale","c":"Le sac vitellin est créé à la suite de l’étranglement du LII, il définit à l’interieur l’intestin primitif et à l’exterieur le sac vitellin","s":"ANNALE Épreuve terminale 2024-2025 Q13"}]},{"name":"Mésoblaste intermédiaire / néphrotomes","facts":[{"t":"1 paire de néphrotomes par somite jusqu’à la 4e paire de somite lombaire.","s":"ANNALE Épreuve terminale 2022-2023 Q28"},{"t":"la segmentation du mésoblaste intermédiaire est incomplète","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"t":"Le métanéphros correspond à la portion non segmentée du mésoblaste intermédiaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"t":"Le mésoblaste intermédiaire est à l’origine du pronéphros, du mésonéphros (qui est une évolution du pronephros), et du métanephros.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}],"pieges":[{"f":"La segmentation du mésoblaste intermédiaire est complète","c":"1 paire de néphrotomes par somite jusqu’à la 4e paire de somite lombaire.","s":"ANNALE Épreuve terminale 2022-2023 Q28"},{"f":"Le mésoblaste intermédiaire sera à l’origine des somites","c":"Il sera à l’origine des néphrotomes.","s":"ANNALE Épreuve terminale 2022-2023 Q24"}]},{"name":"Délimitation / plicatures (céphalo-caudale, latérales)","facts":[{"t":"Les membranes cloacales et pharyngiennes basculent de 180 degrés","s":"ANNALE Épreuve terminale 2022-2023 Q26"},{"t":"Lors des délimitations céphalo-caudales de l’embryon, les membranes pharyngiennes et cloacales réalisent une bascule de 180 degrés.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"A la fin de la délimitation de l’embryon, 4 arcs branchiaux sont visibles à l’extérieur de l’embryon.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"l’allongement important du tube neural intervient dans la plicature céphalique","s":"ANNALE Épreuve terminale 2024-2025 Q13"}],"pieges":[{"f":"A la fin de la délimitation embryonnaire, 5 arcs branchiaux sont visibles à l’extérieur de l’embryon","c":"4 arcs visibles de l’extérieur","s":"ANNALE Rattrapage 2022-2023 Q7"},{"f":"la formation du sac vitellin précède la plicature ventrale","c":"Le sac vitellin est créé à la suite de l’étranglement du LII, il définit à l’interieur l’intestin primitif et à l’exterieur le sac vitellin","s":"ANNALE Épreuve terminale 2024-2025 Q13"}]},{"name":"Cœlome intra-/extra-embryonnaire (4e semaine)","facts":[{"t":"L’ébauche du cœlome interne est bien visible à J20 avec le clivage de la lame latérale mais c’est visible sur une coupe transversale.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"t":"Au cours de la 4ème semaine, le coelome intra-embryonnaire se développe tandis que le coelome extra-embryonnaire se réduit.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Le cœlome extra-embryonnaire prend de moins en moins de place.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Le cœlome interne lui se développe.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"À J 20, on peut voir l’ébauche du coelome interne sur une coupe sagittale.","c":"Attention ! L’ébauche du cœlome interne est bien visible à J20 avec le clivage de la lame latérale mais c’est visible sur une coupe transversale.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q24"},{"f":"Il y a une réduction importante du cœlome interne jusqu’à sa disparition","c":"Du coelome externe, attention ++ point de cours important","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Mésoblaste latéral : péricarde / plèvre / péritoine","facts":[{"t":"le péricarde pariétal provient de la somatopleure","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"Le feuillet pariétal du péricarde dérive bien de la somatopleure (feuillet pariétal du mésoblaste latéral)","s":"ANNALE Rattrapage 2023-2024 Q6"},{"t":"A J20, la lame latérale se clive pour former la splanchnopleure à l’origine du feuillet viscéral et de la somatopleure à l’origine du feuillet pariétal.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2018/2019 Q31"},{"t":"La splanchnopleure est qualifiée de feuillet viscéral","s":"ANNALE Épreuve terminale 2023-2024 QEmbryologie-15 [Mésoblaste et somites]"}],"pieges":[{"f":"Le clivage de la lame latérale va donner la splanchnopleure, futur feuillet pariétal et la somatopleure, futur feuillet viscéral.","c":"C’est l’inverse. A J20, la lame latérale se clive pour former la splanchnopleure à l’origine du feuillet viscéral et de la somatopleure à l’origine du feuillet pariétal.","s":"BANQUE Troisième semaine du développement Concours blanc 1 – 2018/2019 Q31"},{"f":"Le péricarde est formé par la splanchnopleure.","c":"Il est formé par la somatopleure, c’est l’épicarde qui est formé par la splanchnopleure.","s":"BANQUE Mise en place de l’appareil circulatoire Epreuve majeure 2 – 2017/2018 Q28"}]},{"name":"Somites : myotome / dermatome / sclérotome","facts":[{"t":"Les somites se creusent d’une cavité qui est appelé le myocèle","s":"ANNALE Épreuve terminale 2022-2023 Q27"},{"t":"Le dermatome formera le derme et le tissu cellulaire sous-cutané","s":"ANNALE Rattrapage 2022-2023 Q7"},{"t":"La zone interne correspond au myotome, qui forme la musculature striée (épimère et hypomère).","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"c’est la fissure de Von Ebner qui a une densité faible.","s":"ANNALE Épreuve terminale 2024-2025 Q14"}],"pieges":[{"f":"la zone externe du somite correspond au myotome","c":"la zone externe correspond au dermatome","s":"ANNALE Épreuve terminale 2024-2025 Q14"},{"f":"lors de la mise en place des vertèbres, la région crâniale du bloc de sclérotome est de densité cellulaire faible","c":"c’est la fissure de Von Ebner qui a une densité faible.","s":"ANNALE Épreuve terminale 2024-2025 Q14"}]},{"name":"Métanéphros / blastème métanéphrogène","facts":[{"t":"Le métanéphros correspond à la portion non segmentée du mésoblaste intermédiaire.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"t":"Le métanéphros sera à l’origine du futur rein","s":"ANNALE Rattrapage 2022-2023 Q7"},{"t":"Le pronéphros régresse entièrement et ne donne pas le blastème.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"Le métanéphros ne se segmente pas","s":"ANNALE Épreuve terminale 2024-2025 Q15"}],"pieges":[{"f":"Le pronéphros sera à l’origine du blastème métanéphrogène.","c":"Le pronéphros régresse entièrement et ne donne pas le blastème. C’est le métanéphros (portion caudale du mésoblaste intermédiaire) qui donne le blastème métanéphrogène, futur rein.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"f":"Le métanéphros se segmente entre J28 et J32, donnant le blastème métanéphrotique qui est à l’origine du rein.","c":"le métanéphros ne se segmente pas, il se condense entre J28 et J32, ce qui donne bien le blastème métanéphrotique, qui est à l’origine du rein.","s":"BANQUE 4e semaine du développement embryonnaire EM 2 – 2018/2019 Q36"}]},{"name":"Lécithocèle II (étranglement) / sac vitellin","facts":[{"t":"L’allongement du tube neural représente l’événement majeur qui va aboutir à l’étranglement du lécithocèle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Le sac vitellin est créé à la suite de l’étranglement du LII, il définit à l’interieur l’intestin primitif et à l’exterieur le sac vitellin","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"t":"Ces deux plicatures vont aboutir entre autres à un étranglement du lécithocèle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Sur cette coupe on peut observer la plicature cranio-caudale qui est à responsable de l’étranglement du lécithocèle.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q8"}],"pieges":[{"f":"la formation du sac vitellin précède la plicature ventrale","c":"Le sac vitellin est créé à la suite de l’étranglement du LII, il définit à l’interieur l’intestin primitif et à l’exterieur le sac vitellin","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"f":"Il y a une extension active du lécithocèle II","c":"Passive, le LII est victime de l’allongement du tube neural","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Vertèbres / squelette axial / nucleus pulposus","facts":[{"t":"La formation d’une vertèbre fait intervenir 2 paires de somites.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Une vertèbre est constituée à partir d’hémi-somite provenant de somites différents","s":"ANNALE Épreuve terminale 2022-2023 Q27"},{"t":"Lors de la formation du squelette axial, la partie caudale de chaque bloc sclérotomial s'accole à la partie crâniale du bloc sclérotomial sous-jacent","s":"ANNALE Rattrapage 2022-2023 Q7"},{"t":"La formation d’une vertèbre est induite par la chorde et par le tube neural.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"lors de la mise en place des vertèbres, la région crâniale du bloc de sclérotome est de densité cellulaire faible","c":"c’est la fissure de Von Ebner qui a une densité faible.","s":"ANNALE Épreuve terminale 2024-2025 Q14"},{"f":"La formation d’une vertèbre est induite exclusivement par la chorde.","c":"La formation d’une vertèbre est induite par la chorde et par le tube neural. La chorde induit la formation du corps vertébral et le tube neural induit la formation des arcs vertébraux.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}]},{"name":"Dérivés de l'intestin primitif (foie, estomac, duodénum, côlon…)","facts":[{"t":"l’intestin primitif antérieur correspond à la portion allant du pharynx à la portion D2 du duodénum","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"l’ébauche hépatique appartient à l’intestin primitif antérieur","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"t":"le caecum appartient à l’intestin primitif moyen","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"t":"L’intestin antérieur sera vascularisé par le tronc coeliaque, l’intestin moyen par l’artère mésentérique supérieure, et l’intestin postérieur par l’artère mésentérique inférieure.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}],"pieges":[{"f":"la totalité du colon appartient à l’intestin primitif postérieur","c":"Non la séparation IP moyen/postérieur se fait aux 2/3 du colon transverse.","s":"ANNALE Épreuve terminale 2022-2023 Q30"},{"f":"Les artères vitellines vont être dilacérées par l’ébauche hépatique en expansion.","c":"Ce sont les veines vitellines qui vont être dilacérées par l’ébauche hépatique en expansion.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 3 – 2019/2020 Q20"}]},{"name":"Arcs branchiaux / sillons / poches","facts":[{"t":"A la fin de la délimitation de l’embryon, 4 arcs branchiaux sont visibles à l’extérieur de l’embryon.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"4 arcs branchiaux sont bien visibles extérieurement (séparés par 3 sillons ectobranchiaux), tandis que 5 arcs sont visibles intérieurement (avec 4 poches endobranchiales).","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"cinq arcs branchiaux sont visibles à l’intérieur du plancher méso-branchial","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"L’appareil branchial délimite la cavité bucco pharyngienne.","s":"ANNALE Rattrapage 2023-2024 Q5"}],"pieges":[{"f":"A la fin de la délimitation embryonnaire, 5 arcs branchiaux sont visibles à l’extérieur de l’embryon","c":"4 arcs visibles de l’extérieur","s":"ANNALE Rattrapage 2022-2023 Q7"},{"f":"l’axe mésenchymateux des arcs branchiaux possède une origine triple : mésoblaste para-axial, cellules des crêtes neurales et tissus ectoblastiques","c":"il possède une origine DOUBLE : mésoblaste para-axiale et latéral, ET cellules des crêtes neurales céphaliques","s":"ANNALE Épreuve terminale 2024-2025 Q16"}]},{"name":"Neuropores (céphalique J24 / caudal J26)","facts":[{"t":"Les neuropores céphalique et caudal se ferment respectivement à J24 et J26.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"t":"Le neuropore céphalique se ferme à J24, et le caudal à J26.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"A J24, alors que le neuropore postérieur/caudal à J26","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"ET le neuropore ANTERIEUR (2 ouvertures)","s":"ANNALE Épreuve terminale 2022-2023 Q25"}],"pieges":[{"f":"Le tube neural ne possède qu’une ouverture : le neuropore postérieur","c":"ET le neuropore ANTERIEUR (2 ouvertures)","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"f":"Le mésencéphale communique avec le neuropore antérieur","c":"Ces éléments ne sont pas visualisés au même moment du développement","s":"ANNALE Épreuve terminale 2022-2023 Q29"}]},{"name":"Mésonéphros / canal de Wolff","facts":[{"t":"l’extrémité distale des tubules mésonéphrotiques sera à l’origine des chambres glomérulaires","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"t":"le corps de Wolff est enveloppé par l’épithélium cœlomique","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"t":"L’extrémité distale des tubules mésonéphrotiques s'enfle et s'organise en chambre glomérulaire","s":"ANNALE Épreuve terminale 2022-2023 Q28"},{"t":"Le mésoblaste intermédiaire est à l’origine du pronéphros, du mésonéphros (qui est une évolution du pronephros), et du métanephros.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}],"pieges":[{"f":"Le pronéphros et le mésonéphros vont coexister pendant plusieurs jours.","c":"Le pronephros est une structure présente entre J20 et J25. Le mésonephros prend le relai du pronephros, donc ces deux structures ne peuvent pas coexister.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"f":"le mésonéphros est à l’origine du canal de Wolff","c":"c’est le rôle du pronéphros","s":"ANNALE Épreuve terminale 2024-2025 Q15"}]},{"name":"Paroi ventrale / flancs latéraux","facts":[{"t":"Les flancs latéraux apparaissent à J24, lorsqu’il y a environ 20 paires de somites.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2– 2019/2020 Q24"},{"t":"Apparition des flancs latéraux et stade « 20 paires de somites ».","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q32"},{"t":"La paroi ventrale de l’embryon finit de se former à J25 cependant elle n’est jamais totalement fermée et reste ouverte au niveau de la vésicule vitelline qui est en communication avec l’intestin primitif.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q2"},{"t":"Les flancs latéraux apparaissent à J24.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 3 – 2019/2020 Q13"}],"pieges":[{"f":"la formation de la paroi ventrale est consécutive à une extension active de la cavité amniotique","c":"la cavité amniotique s’étend de manière passive !","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"f":"À J25 La paroi ventrale de l’embryon est totalement fermée.","c":"La paroi ventrale de l’embryon finit de se former à J25 cependant elle n’est jamais totalement fermée et reste ouverte au niveau de la vésicule vitelline qui est en communication avec l’intestin primitif. Cela permet aussi de garder une communication entre les cœlomes interne et externe.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q2"}]},{"name":"Pronéphros","facts":[{"t":"Le mésoblaste intermédiaire est à l’origine du pronéphros, du mésonéphros (qui est une évolution du pronephros), et du métanephros.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"},{"t":"Le pronéphros régresse entièrement et ne donne pas le blastème.","s":"ANNALE Rattrapage 2023-2024 Q4"},{"t":"Fin J20, 7 paires de tubules s’aplatissent et s’allongent pour former le pronéphros.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 2 – 2019/2020 Q14"},{"t":"Pronéphros disparait à J25, fermeture neuropore caudal J26.","s":"BANQUE 4e semaine du développement embryonnaire Concours Blanc n°2 – 2019/2020 - Médecine Q1"}],"pieges":[{"f":"le pronéphros perdure jusqu’à la naissance","c":"il régresse à J28, au bout de 5 jours","s":"ANNALE Épreuve terminale 2024-2025 Q15"},{"f":"Le pronéphros et le mésonéphros vont coexister pendant plusieurs jours.","c":"Le pronephros est une structure présente entre J20 et J25. Le mésonephros prend le relai du pronephros, donc ces deux structures ne peuvent pas coexister.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q26"}]},{"name":"Crêtes neurales","facts":[{"t":"il possède une origine DOUBLE : mésoblaste para-axiale et latéral, ET cellules des crêtes neurales céphaliques","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"t":"Une mauvaise migration des crêtes neurales pourra avoir des répercussions autant sur des structures nerveuses que non nerveuses. Épreuve majeure n°2 – 2020/2021","s":"BANQUE Troisième semaine du développement Concours blanc n°1 – 2020/2021 Q11"},{"t":"Une anomalie de la pigmentation de la peau peut être due à un défaut de migration des cellules des crêtes neurales.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q27"},{"t":"Le mégacôlon congénital est dû à une mauvaise migration des cellules des crêtes neurales.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q31"}],"pieges":[{"f":"l’axe mésenchymateux des arcs branchiaux possède une origine triple : mésoblaste para-axial, cellules des crêtes neurales et tissus ectoblastiques","c":"il possède une origine DOUBLE : mésoblaste para-axiale et latéral, ET cellules des crêtes neurales céphaliques","s":"ANNALE Épreuve terminale 2024-2025 Q16"},{"f":"Les cellules des crêtes neurales correspondent à des cellules du fond de la gouttière neurale qui se sont détachées et qui migrent à l’extérieur","c":"Sur les bords de la gouttière neurale et pas au fond.","s":"ANNALE Épreuve terminale 2022-2023 Q25"}]},{"name":"Neurulation primaire","facts":[{"t":"La neurulation primaire débute par un épaississement d’une partie de l’ectoblaste sous l’effet inducteur de la chorde","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"La deuxième étape de la neurulation primaire correspond à la fusion des bords de la gouttière neurale","s":"ANNALE Épreuve terminale 2022-2023 Q25"},{"t":"La neurulation secondaire fait intervenir le bourgeon caudal mésoblastique","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"Le rhombencéphale est une des 3 vésicules de la neurulation primaire, formées à l’extrémité antérieure du tube neural.","s":"ANNALE Rattrapage 2023-2024 Q5"}],"pieges":[{"f":"La neurulation secondaire est réalisée avec de l’entoblaste.","c":"La neurulation secondaire se fait à partir du mésoblaste (bourgeon caudal mésoblastique), pas de l'entoblaste.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"f":"Le rhombencéphale est l’une des vésicules mises en place lors de la neurulation secondaire.","c":"Le rhombencéphale est une des 3 vésicules de la neurulation primaire, formées à l’extrémité antérieure du tube neural.","s":"ANNALE Rattrapage 2023-2024 Q5"}]},{"name":"Allongement du tube neural / extension de la cavité amniotique","facts":[{"t":"l’allongement important du tube neural intervient dans la plicature céphalique","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"t":"L’allongement du tube neural représente l’événement majeur qui va aboutir à l’étranglement du lécithocèle.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Passive, le LII est victime de l’allongement du tube neural","s":"ANNALE Épreuve terminale 2022-2023 Q26"},{"t":"L’allongement du tube neural entraîne une extension de la cavité amniotique et une bascule des membranes pharyngiennes et cloacales.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"}],"pieges":[{"f":"la formation de la paroi ventrale est consécutive à une extension active de la cavité amniotique","c":"la cavité amniotique s’étend de manière passive !","s":"ANNALE Épreuve terminale 2024-2025 Q13"},{"f":"Il y a une extension active du lécithocèle II","c":"Passive, le LII est victime de l’allongement du tube neural","s":"ANNALE Épreuve terminale 2022-2023 Q26"}]},{"name":"Vésicules cérébrales (rhombencéphale, mésencéphale, prosencéphale)","facts":[{"t":"Le rhombencéphale communique avec le tube médullaire primitif","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"Le mésencéphale correspond à la deuxième vésicule de l’extrémité antérieure du tube neural","s":"ANNALE Rattrapage 2022-2023 Q8"},{"t":"Le rhombencéphale est une des 3 vésicules de la neurulation primaire, formées à l’extrémité antérieure du tube neural.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"Le diencéphale est issu de la transformation du prosencéphale (cerveau antérieur) durant le 2ème mois.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2017/2018 Q53"}],"pieges":[{"f":"Le mésencéphale communique avec le neuropore antérieur","c":"Ces éléments ne sont pas visualisés au même moment du développement","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"f":"Le rhombencéphale est l’une des vésicules mises en place lors de la neurulation secondaire.","c":"Le rhombencéphale est une des 3 vésicules de la neurulation primaire, formées à l’extrémité antérieure du tube neural.","s":"ANNALE Rattrapage 2023-2024 Q5"}]},{"name":"Gouttière / ébauche respiratoire","facts":[{"t":"La première ébauche de l’appareil respiratoire est d’origine entoblastique et apparaît aux alentours de J22.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q26"},{"t":"La gouttière respiratoire apparaît à J22.","s":"BANQUE 4e semaine du développement embryonnaire Epreuve majeure 2 – 2017/2018 Q50"},{"t":"la gouttière respiratoire se développe à partir de l’intestin antérieur à J22.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q26"},{"t":"le neuropore crânial se ferme à J24 et l’ébauche respiratoire apparaît à J22, à partir de l’endoblaste.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q32"}],"pieges":[{"f":"La gouttière respiratoire d’origine ectoblastique est mise en place à J22.","c":"La gouttière respiratoire est d’origine ENDOblastique en effet elle se développe à partir de l’intestin primitif antérieur. Sa formation a cependant bien lieu à J22.","s":"BANQUE 4e semaine du développement embryonnaire Épreuve majeure n°2 – 2019/2020 Q9"},{"f":"Fermeture du neuropore crânial et ébauche respiratoire à partir de l’endoblaste.","c":"le neuropore crânial se ferme à J24 et l’ébauche respiratoire apparaît à J22, à partir de l’endoblaste.","s":"BANQUE 4e semaine du développement embryonnaire CCB 1 – 2018/2019 Q32"}]},{"name":"Neurulation secondaire","facts":[{"t":"La neurulation secondaire fait intervenir le bourgeon caudal mésoblastique","s":"ANNALE Épreuve terminale 2022-2023 Q29"},{"t":"La neurulation secondaire explique que l’ensemble du système nerveux ne soit pas exclusivement d’origine ectoblastique.","s":"BANQUE 4e semaine du développement embryonnaire Concours Blanc – 2015/2016 Q64"},{"t":"La neurulation secondaire débute bien au début de la 4e semaine où on a formation du tube neural qui s’arrête en S2 en dessous on a un cordon plein : l’éminence caudale mésenchymateuse.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2020/2021 Q6"},{"t":"La partie mésoblastique apparaît pendant la neurulation secondaire.","s":"BANQUE 4e semaine du développement embryonnaire EM 2 – 2018/2019 Q37"}],"pieges":[{"f":"La neurulation secondaire est réalisée avec de l’entoblaste.","c":"La neurulation secondaire se fait à partir du mésoblaste (bourgeon caudal mésoblastique), pas de l'entoblaste.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"f":"Le rhombencéphale est l’une des vésicules mises en place lors de la neurulation secondaire.","c":"Le rhombencéphale est une des 3 vésicules de la neurulation primaire, formées à l’extrémité antérieure du tube neural.","s":"ANNALE Rattrapage 2023-2024 Q5"}]},{"name":"Spina bifida / anencéphalie / défauts de fermeture","facts":[{"t":"Un spina bifida correspond à l’ouverture de la moelle épinière à la surface du corps.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"Le spina bifida est une anomalie de fermeture du tube neural, exposant parfois la moelle (spina bifida aperta ou myéloméningocèle).","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"Le spina bifida est la conséquence d’une anomalie de fermeture du canal médullaire.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q27"},{"t":"Le cas le plus fréquent est le myéloméningocèle dans lequel les enveloppes de la moelle s’ouvrent avec celle-ci à la surface du corps.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q27"}],"pieges":[{"f":"L’acide folique (ou vitamine B9) peut induire des anomalies de fermeture du tube neural causant par exemple un spina bifida.","c":"C’est au contraire un facteur protecteur de cette malformation. On donne en prévention de l’acide folique aux femmes en début de grossesse.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2017/2018 Q48"},{"f":"Une mauvaise migration des crêtes neurales peut-être à l’origine d’une anencéphalie.","c":"Une anencéphalie a pour origine une mauvaise fermeture du neuropore antérieur du tube neural. Une spina bifida provient d’une mauvaise fermeture du neuropore postérieur, attention à ne pas confondre.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc – 2016/2017 Q56"}]},{"name":"Cavité bucco-pharyngienne / bouche primitive","facts":[{"t":"L’appareil branchial délimite la cavité bucco pharyngienne.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"L’appareil branchial entoure la cavité bucco-pharyngienne, située entre les arcs branchiaux.","s":"ANNALE Rattrapage 2023-2024 Q5"},{"t":"La membrane pharyngienne se résorbe bien entre J26 et J28 pour former la bouche primitive point de départ du tube digestif en revanche la membrane cloacale ne se résorbe pas encore.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2020/2021 Q6"},{"t":"Les ébauches pancréatique et hépatique se développent à partir de l’intestin antérieur compris entre la bouche primitive et la deuxième partie du duodénum.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc n°2 – 2020/2021 Q1"}],"pieges":[{"f":"Les membranes pharyngienne et cloacale se résorbent.","c":"La membrane pharyngienne se résorbe bien entre J26 et J28 pour former la bouche primitive point de départ du tube digestif en revanche la membrane cloacale ne se résorbe pas encore. C’est pourquoi à ce stade les voies urinaires (allantoïde) et digestives (rectum) ne sont pas distinctes et débouchent toutes les deux dans un unique cloaque.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 1 – 2020/2021 Q6"}]},{"name":"Stade phylotypique","facts":[{"t":"Le stade phylotypique est très semblable pour l’ensemble des embryons de vertébrés.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"Le stade phylotypique est bien un stade commun aux embryons vertébrés.","s":"ANNALE Épreuve terminale Embryologie 2020-2021 Q25"},{"t":"À la fin du 1er mois, les embryons sont branchiaux et caudés, ils sont au stade phylotypique.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc – 2016/2017 Q54"},{"t":"l’aspect extérieur de l’embryon à la fin de la 4ème semaine correspond bien au stade phylotypique, mais ce stade est justement commun aux embryons vertébrés.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q25"}],"pieges":[{"f":"L’aspect extérieur de l’embryon à la fin de la 4ème semaine est spécifique de l’espèce humaine et est appelé stade phylotypique.","c":"l’aspect extérieur de l’embryon à la fin de la 4ème semaine correspond bien au stade phylotypique, mais ce stade est justement commun aux embryons vertébrés.","s":"BANQUE 4e semaine du développement embryonnaire CCB 2 – 2018/2019 Q25"},{"f":"À la fin du premier mois, l’embryon humain a un aspect spécifique de son espèce.","c":"On parle de stade phylotypique qui est commun à tous les embryons vertébrés.","s":"BANQUE 4e semaine du développement embryonnaire Concours blanc 2 – 2017/2018 Q40"}]}]}];
